WITH payload AS (SELECT $archive_payload$[{"id":"c8096838-5c07-5518-8aaf-de0e906af23c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج مخدرات -ترويج احلشيش املخدر و احلبوب احملظورة -تعاطي احلشيش املخدر -حيازة احلشيش املخدر واحلبوب احملظورة -إقرار -التعزير بالسجن واجللد و اإلبعاد عن الباد ومصادرة هاتفه اجلوال و إيقاف الشريحة -إقامة حد املسكر على متعاطي احلشيش.","document_number":"33473663","case_number":"3429882","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/20","year":"1434","subject":"مخدرات -ترويج مخدرات -ترويج احلشيش املخدر و احلبوب احملظورة -تعاطي احلشيش املخدر -حيازة احلشيش املخدر واحلبوب احملظورة -إقرار -التعزير بالسجن واجللد و اإلبعاد عن الباد ومصادرة هاتفه اجلوال و إيقاف الشريحة -إقامة حد املسكر على متعاطي احلشيش.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33473663 :‬تاريخه ‪1433/12/20 :‬هـ‬\n                     ‫رقم الدعوى ‪3429882 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3439894‬تاريخه‪1434/2/18 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج مخــدرات ‪ -‬ترويــج احلشــيش املخــدر و احلبــوب‬\n ‫احملظــورة ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬حيــازة احلشــيش املخــدر‬\n ‫واحلبــوب احملظــورة ‪ -‬إقــرار‪ -‬التعزيــر بالســجن واجللــد و اإلبعــاد عــن‬\n ‫البــاد ومصــادرة هاتفــه اجلــوال و إيقــاف الشــريحة ‪ -‬إقامــة حــد املســكر‬\n                                                  ‫علــى متعاطــي احلشــيش‪.‬‬\n\n\n\n\n           ‫‪ -‬املادة ( ‪ ) 38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ -‬املادة ( ‪ ) 53‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ -‬املادة ( ‪ ) 56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ -‬املادة ( ‪ ) 60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج احلبــوب احملظــورة‬\n ‫واحلشــيش املخدر ‪ ،‬حيث ورد بالغ من أحد املصادر الســرية أن املدعى‬\n ‫عليــه يقــوم بترويــج املخــدرات‪ ،‬ومت التنســيق معــه من قبل املصدر لشــراء‬\n ‫حبــوب الكبتاجــون احملظــورة‪ ،‬مببلــغ ثــاث مائــة ريــال‪ ،‬وقطعــة مــن‬\n ‫احلشــيش املخــدر مببلــغ ثــاث مائــة ريــال‪ ،‬ومت تكليــف أحــد األفــراد‬\n ‫أن يقــوم بــدور املشــتري‪ ،‬وتزويــده باملبلــغ املرقــم مبرافقــة املصــدر‪ ،‬ثــم‬\n\n                                                                                     ‫‪346‬‬\n\f      ‫ســلم املدعــى عليــه لفــرد املكافحــة حبــوب الكبتاجــون احملظــورة‪،‬‬\n      ‫كمــا ســلمه قطعــه يشــتبه أن تكــون مــن احلشــيش املخــدر ‪ ،‬كمــا‬\n      ‫عثــر معــه علــى حبــوب حتمــل عالمــة الكبتاجــون احملظــورة‪ ،‬وقطعــة‬\n      ‫ســوداء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر‪ ،‬وعلــى املبلــغ‬\n      ‫املرقــم وقــدره ســتمائة ريــال ‪ ،‬كمــا عثــر معــه علــى اجلــوال املســتخدم يف‬\n      ‫اجلرميــة‪ ،‬وبتفتيــش الســيارة عثــر فيهــا علــى قطعــة ســوداء اللــون‪ ،‬يشــتبه‬\n      ‫أن تكــون مــن احلشــيش املخــدر ومت القبــض عليــه وطلــب املدعــي العــام‬\n      ‫تعزيــر املدعــى عليــه بالســجن و اجللــد و اإلبعــاد عــن البــاد و الغرامــة و‬\n      ‫مصــادرة هاتفــه اجلــوال و إلغــاء الشــريحة املســتخدمة وتعزيــره لقــاء‬\n      ‫تســتره علــى مصــدر مــا ضبــط معــه ومــا مت ترويجــه و ذلــك بتطبيــق‬\n      ‫املــواد ( ‪ )56/53/38‬مــن نظــام مكافحــه املخــدرات و املؤثــرات العقليــة‬\n      ‫بحقه‪،‬وطلــب املقتضــى الشــرعي لقــاء تعاطيــه احلشــيش املخــدر ‪ ،‬كمــا‬\n      ‫أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ‪،‬وبنــاء علــى ماتقــدم‬\n      ‫حكمــت احملكمــة بإقامــة حــد املســكر بحــق املدعــى عليــه والتعزيــر‬\n      ‫بالســجن و اجللــد و اإلبعــاد عــن البــاد و مصــادرة هاتفــه النقــال و إلغــاء‬\n      ‫الشــريحة و تعزيــره لقــاء تســتره علــى مصــدر مــا مت ضبطــه معــه و مــا مت‬\n      ‫ترويجــه و مت النــزول عــن احلــد األدنــى مــن العقوبــة بنــاء علــى املــادة (‪)60‬‬\n      ‫مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة لكونــه أجنبــي وال‬\n      ‫فائــدة مــن إطالــة ســجنه ‪ ،‬و قــرر املدعــى عليــه قناعتــه باحلكــم ‪ ،‬وقــرر‬\n      ‫وصــدق احلكــم مــن‬   ‫املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة ُ‬\n                                                                 ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪347‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1434/06/28‬ه ـ املقيــدة باحملكمــة‬\n‫برقم وتاريخ ‪1434/06/28‬هـ ففي يوم األحد املوافق‪1434/07/30‬هـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 15‬صباحــا ويف هــذه اجللســة قــدم املدعــي‬\n‫عضــو هيئــة التحقيــق واالدعــاء العــام بالريــاض وادعــى علــى‪ ،:‬البالــغ‬\n‫مــن العمــر (‪ )31‬عام ـ ًا ‪ ،‬فلســطيني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم () ‪ ،‬متــزوج ‪ ،‬متعلــم ‪ ،‬مرافــق لوالــده ‪ ،‬مســلم ‪ ،‬يقيــم مبدينــة‬\n‫الريــاض ‪ ،‬أوقــف بتاريــخ ‪1434/4/20‬ه ـ وأودع بشــعبة ســجن امللــز‬\n‫مبوجــب أمــر اإلحالــة ومتديــد التوقيــف رقــم (ه ـ ر‪ )43766/5/1‬وتاريــخ‬\n‫‪1434/ 4 / 29‬ه ـ اســتناد ًا إلــى القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n‫قائــا‪ :‬أنــه بتاريــخ ‪1434/4/20‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى‬\n‫فــرق مكافحــة املخــدرات بنــاء للمعلومــات الــواردة مــن أحــد مصادرهــم‬\n‫الســرية عــن وجــود شــخص فلســطيني اجلنســية يقــوم بترويــج احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة ويســكن بحــي ‪ ........‬وبالتنســيق مــع املصــدر‬\n‫جــرى االتصــال علــى املــروج املذكــور علــى اجلــوال رقــم () ومت االتفــاق‬\n‫معــه علــى شــراء حبــوب الكبتاجــون احملظــور مببلــغ (‪ )300‬ثالثمائــة‬\n‫ريــال وقطعــة مــن احلشــيش املخــدر مببلــغ (‪ )300‬ثالثمائــة ريــال ومت‬\n‫تكليــف أحــد أفــراد الفرقــة مبرافقــه املصــدر يف شــقته والقيــام بــدور‬\n‫املشــتري ومت تزويــده باملبلــغ املرقــم وعنــد دخولهــم لشــقه املصــدر مت‬\n\n                                                                                   ‫‪348‬‬\n\f      ‫االتصــال علــى املــروج لتتــم عمليــه الشــراء وذكــر أن املخــدرات معــه‬\n      ‫وعلــى أمت االســتعداد وبعــد حوالــي عشــر دقائــق حضــرت ســيارة مــن نــوع‬\n      ‫‪ ....‬حتمــل اللوحــة رقــم (‪( )-‬جــرى تســليم الســيارة للشــركة املؤجــرة‬\n      ‫باخلطــاب رقــم ه ـ ر‪0861 /5/1‬وتاريــخ ‪1434/ 5 /18‬ه ـ ) يقودهــا‬\n      ‫شــخص تنطبــق عليــه أوصــاف املــروج املذكــور ثــم دخــل إلــى شــقه‬\n      ‫املصــدر وقابــل عنصــر املكافحــة وســلم مــا عدده (‪ )9‬تســع حبات حتمل‬\n      ‫عالمــة (الكبتاجــون) احملظــور كمــا ســلم قطعــة يشــتبه أن تكــون‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )9.3‬تســعه جرامــات وثالثــة أعشــار‬\n      ‫اجلــرام واســتلم املبلــغ املرقــم وكانــت الفرقــة القابضــة أمــام العمــارة‬\n      ‫وعنــد نزولــه مت القبــض عليــه واتضــح أنــه املذكــور أعــاه وبتفتيشــه‬\n      ‫عثــر يف جيــب بنطالــه األيســر علــى املبلــغ املرقــم وقــدره (‪ )600‬ســتمائة‬\n      ‫ريــال كمــا عثــر يف جيبــه األميــن علــى مــا عــدده (‪ )13.5‬ثالثــة عشــر‬\n      ‫حبــة ونصــف احلبــة حتمــل عالمــة الكبتاجــون احملظــور وقطعــة ســوداء‬\n      ‫اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )11.7‬إحــدى‬\n      ‫عشــر جرامـ ًا وســبعه أعشــار اجلــرام وكذلــك مبلــغ وقــدره (‪ )170‬مائــه‬\n      ‫وســبعون ريــا ًال وجــوال ‪....‬ويحمــل الرقــم املصنعــي (‪ )....‬وبداخلــه شــريحة‬\n      ‫‪....‬املســتخدم يف اجلرميــة وجــوال ‪ ....‬بداخلــه شــريحة ‪ ( ....‬مت رده مبوجــب‬\n      ‫اخلطــاب رقــم ‪ ...........‬ه ـ ر‪ ..... /5/1‬وتاريــخ ‪1434/../..‬ه ـ ) وبتفتيــش‬\n      ‫الســيارة عثــر يف البــاب األمامــي األيســر علــى قطعــة ســوداء اللــون يشــتبه‬\n      ‫أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )49‬تســعه وأربعــون جرامـ ًا ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n      ‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم‬\n      ‫(‪/4829‬س) لعــام ‪1434‬ه ـ احتــواء احلبــوب املروجــة واحلبــوب املضبوطــة‬\n\n\n‫‪349‬‬\n\f‫ملــادة االمفيتامــن وهــو مــن املــواد املنبهــة واملدرجــة باجلــدول رقــم (‪)2‬‬\n‫فئــة (ب) مــن نظــام مكافحــه املخــدرات واملؤثــرات العقليــة وإيجابيــة‬\n‫عينــة القطــع املروجــة وعينتــي القطــع املضبوطــة ملــادة احلشــيش وهــو‬\n‫مــن املــواد املخــدرة و املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنفــس‬\n                                                           ‫النظــام املشــار إليــه ‪.‬‬\n‫وبســماع أقوالــه األوليــة وباســتجوابه اعتــرف بحيــازة مــا ضبــط مــن‬\n‫حشــيش مخــدر وحبــوب محظــورة بقصــد التعاطــي واعتــرف بتعاطــي‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة وأفــاد بــأن املبلــغ املالــي املضبــوط‬\n‫معــه وقــدره (‪ )170‬مائــة وســبعون ريــا ًال هــو أجــرة عملــة يف ورشــة لصيانة‬\n‫الســيارات ( مت رده مبوجــب اخلطــاب رقــم ه ـ ر‪60007 /5/1‬وتاريــخ‬\n                                                           ‫‪1434/ 6 /13‬ه ـ ) ‪.‬‬\n‫وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام ‪ )9( ........‬تســع‬\n‫حبــات مــن حبــوب االمفيتامــن املنبهــة احملظــورة وقطعــة حشــيش تــزن‬\n‫(‪ )9.3‬تســعه جرامــات وثالثــة أعشــار اجلــرام بقصــد االجتــار والترويــج‬\n‫وحيــازة (‪ )13.5‬ثالثــة عشــر حبــه ونصــف احلبــة مــن حبــوب االمفيتامــن‬\n‫املنبهــة احملظــورة وقطعتــن مــن احلشــيش املخــدر تــزن جميع ـ ًا (‪)60.7‬‬\n‫ســتون جرامـ ًا وســبعه أعشــار اجلــرام بقصــد الترويــج والتعاطــي وتعاطيــه‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا مت‬\n                            ‫ترويجــه ومــا ضبــط املعاقــب علــى ذلــك شــرع ًا ‪.‬‬\n                                           ‫وذلك لألدلة والقرائن التالية ‪-:‬‬\n‫‪ -1‬مــا تضمنــه اعترافــه حتقيق ـ ًا املنــوه عنــه املــدون علــى الصفحــات‬\n\n\n                                                                                        ‫‪350‬‬\n\f                          ‫(‪1‬ـ‪ )2‬مــن دفتــر التحقيــق املرفــق لفــه رقــم ( ‪. ) 14‬‬\n      ‫‪ -2‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه‬\n                                                    ‫واملرفــق علــى اللفتــن رقــم (‪8‬ـ‪. )9‬‬\n      ‫‪ -3‬مــا تضمنــه محضــر القبــض املنــوه عنــه واملــدون علــى الصفحــات رقــم‬\n                   ‫(‪11‬ـ‪ )12‬مــن دفتــر محاضــر االســتدالل املرفــق لفــه رقــم ( ‪. ) 1‬‬\n      ‫‪ -4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه‬\n                                                                              ‫رقــم ( ‪. ) 18‬‬\n      ‫‪ -5‬محضــر مطابقــة املبلــغ املرقــم املــدون علــى الصفحــة رقــم (‪ )4‬مــن‬\n                                   ‫ملــف إجــراءات االســتدالل املرفــق لفــة رقــم (‪. )1‬‬\n      ‫وببحــث ســوابقه اتضــح عــدم وجــود ســوابق جنائيــة مســجلة عليــة حتــى‬\n                                                                                       ‫تاريخــه ‪.‬‬\n      ‫وحيــث أن مــا أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم وم ــعاقب عليــه شــرع ًا‬\n      ‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪:‬‬\n      ‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه وتشــديد العقوبــة عليــه وفقـ ًا للفقــرة (ج) البنــد ثانيـ ًا مــن نفــس املــادة‬\n      ‫وأعمــال الفقــرة (األولــى) مــن املــادة (‪ )62‬مــن ذات النظــام بحقــه لقــاء‬\n                                                                               ‫مــا اســند إليــه‪.‬‬\n               ‫‪-2‬إجراء املقتضى الشرعي بحقه لقاء تعاطيه احلشيش املخدر ‪.‬‬\n      ‫‪-3‬إبعــاده إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه وعــدم‬\n      ‫الســماح لــه بالعــودة إليهــا مــره أخــرى وفق ـ ًا للفقــرة (الثانيــة) مــن املــادة‬\n                                                    ‫(‪ )56‬مــن نفــس النظــام املشــار إليــه‪.‬‬\n      ‫‪-4‬مصــادرة الهاتــف النقــال مــن نــوع (‪ )....‬املســتخدم يف اجلرميــة ذو‬\n\n\n‫‪351‬‬\n\f‫الرقــم املصنعــي ‪ ......‬اســتناد ًا للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن نظــام‬\n                                    ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫‪-5‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة ذات الرقــم ‪ .......‬وعــدم صرفها‬\n‫لنفــس املشــترك يف حــال صــدور احلكــم باإللغــاء وإبــاغ الشــركة‬\n‫مصــدرة الشــريحة بذلــك اســتناد ًا إلــى تعميــم ســمو وزيــر الداخليــة رقــم‬\n                                           ‫(‪ )9798‬وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n‫‪ -6‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط ومــا مت‬\n                                                                            ‫ترويجــه ‪.‬‬\n‫ويف هــذه اجللســة حضــر املدعــى عليــه وبعــرض دعــوى املدعــي العــام‬\n‫علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام مــن القبــض‬\n‫علــي وقيامــي بتســليم املصــدر (‪ )9‬حبــات مــن الكبتاجــون وقطعــة مــن‬\n‫احلشــيش تــزن (‪ )9.3‬تســعة جرامــات وثالثــة أعشــار اجلــرام واســتالم‬\n‫قيمتهــا مــن املصــدر مببلــغ ســتمائة ريــال صحيــح ولكــن املصــدر هــو‬\n‫الــذي طلــب منــي شــراءها مــن أحــد األشــخاص الذيــن يعرفهــم وقمــت‬\n‫بذلــك واشــتريت مــا يخصنــي ومــا يخــص املصــدر وســلمته مــا يخصــه‬\n‫منهــا ولــم يكــن قصــدي بذلــك االجتــار ببيــع احلبــوب واحلشــيش املخــدر‬\n‫وأمــا باقــي الكميــة املضبوطــة معــي فهــي لــي بقصــد التعاطــي وليــس‬\n‫بقصــد الترويــج كمــا أقــر بتعاطــي احلشــيش املخــدر واحلبــوب املنبهــة‬\n‫وأمــا مصــدر مــا ضبــط معــي هــو لشــخص باكســتاني اجلنســية يحضــر‬\n‫لــي عنــد الورشــة وال أعلــم اســمه وال مكانــه‪ .‬وبنــاء علــى مــا ســبق مــن‬\n‫الدعــوى واإلجابــة فقــد ثبــت لــدي إدانــة املدعــى عليــه بالتوســط يف بيــع‬\n‫وشــراء (‪ )9‬تســع حبــات مــن حبــوب االمفيتامــن املنبهــة احملظورة وقطعة‬\n‫حشــيش مخــدر تــزن (‪ )9.3‬تســعة جرامــات وثالثــة أعشــار اجلــرام بقصــد‬\n\n\n                                                                                          ‫‪352‬‬\n\f      ‫الترويــج وحيــازة (‪ )13.5‬ثالثــة عشــر حبــة ونصــف احلبــة مــن حبــوب‬\n      ‫االمفيتامــن املنبهــة احملظــورة وقطعتــن مــن احلشــيش املخــدر تزنــان‬\n      ‫جميعــا (‪ )60.7‬ســتون جرامــا وســبعة أعشــار اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطيــه احلشــيش املخــدر واحلبــوب احملظــورة وتســتره علــى مصــدر مــا‬\n      ‫مت ترويجــه‪ .‬وألن هــذا الفعــل محــرم شــرعا وموجــب للحــد والتعزيــر‬\n      ‫ولتوفــر إقامــة احلــد علــى املدعــى عليــه فقــد حكمــت علــى املدعــى عليــه‬\n                                                                                ‫مبــا يلــي‪:‬‬\n      ‫أوال‪ /‬ســجنه مــدة ســنتني اعتبــارا مــن تاريــخ ايقافــه وجلــده مائتــا جلــده‬\n      ‫مفرقــة علــى أربــع دفعــات متســاويات كل عشــرة أيــام وتغرميــه ألــف‬\n      ‫ريــال لقــاء توســطه يف بيــع احلشــيش املخــدر واحلبــوب احملظــورة لقصــد‬\n      ‫الترويــج ولقــاء حيازتــه ملثلهــا لقصــد التعاطــي بنــاء علــى املــادة (‪ )38‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإعمــاال للمــادة (‪ )62‬مــن‬\n      ‫النظــام ذاتــه ونــزوال عــن احلــد األدنــى مــن الســجن لعــدم وجــود ســوابق‬\n      ‫علــى املدعــى عليــه ولقلــة الكميــة ولكونــه أجنبــي وال فائــدة للبلــد مــن‬\n                                                                          ‫إطالــة ســجنه‪.‬‬\n      ‫ثانيــا‪ /‬جلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر علــى أن يكــون‬\n                                               ‫بــن جلــد احلــد والتعزيــر عشــرة أيــام‪.‬‬\n      ‫ثالثــا‪ /‬ابعــاده خــارج البــاد بعــد انتهــاء وتنفيــذ عقوبــة ســجنه وعــدم‬\n      ‫الســماح لــه بالعــودة إال مبــا تقتضيــه تعليمــات للحــج والعمــرة بنــاء علــى‬\n                                                        ‫املــادة (‪ )56‬مــن النظــام ذاتــه‪.‬‬\n      ‫رابعــا‪ /‬مصــادرة الهاتــف النقــال املضبــوط يف اجلرميــة واملذكــور يف‬\n      ‫الدعــوى وايقــاف الشــريحة املســتخدمة بنــاء علــى املــادة ‪ 53‬مــن النظــام‬\n      ‫ذاتــه‪ .‬واالكتفــاء مبــا ســبق كعقوبــة علــى تســتره علــى مصــدر ما ضبط‬\n\n\n‫‪353‬‬\n\f‫معــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم القناعــة‬\n‫وعــدم رغبتــه بتقــدمي الئحــة اعتراضيــة واالكتفــاء مبــا ورد يف الئحــة‬\n‫الدعــوى وقــرر املدعــى عليــه القناعــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/30‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ‬\n‫‪1434/9/23‬ه ـ املرفــق بهــا القــرار الصــادر مــن القاضــي باحملكمــة‬\n‫الشــيخ‪ /‬برقــم وتاريــخ ‪1434/8/1‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n‫ضــد ‪( ........‬فلســطيني اجلنســية) التهامــه يف قضيــة مخــدرات على النحو‬\n‫املوضــح بالقــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون مفصــل بــه‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n‫احلكــم مــع تنبيــه فضيلتــه لذكــر مســوغ النــزول عــن العقوبــة وهــي‬\n‫املــادة الســتني مــن نظــام مكافحــة املخــدرات يف القــرار قبــل بعــث‬\n‫املعاملــة جلهــة التنفيــذ ‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                            ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪354‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":346,"source_page_end":354,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"17a72290735aa0ef2a8e1dd85d7dea5e622f659c766f829eea749d5f3959c6cc","normalized_text_hash":"eded2084de4a39bd6b2008796418637a7401d0ab83b8d4eecb2a421177e601c2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p346-33473663"},{"id":"034e343c-a64a-5c7d-badb-47f3056ad99a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة «الكبتاجون» -إهداء احلبوب احملظورة -تعاطي احلبوب احملظورة -مقاومة قوات الشرطة - إنكار الترويج واالقرار باحليازة والتعاطي -ثبوت اإلدانة بالترويج والبيع واالهداء -تخفيف العقوبة لقلة الكمية ولعدم وجود سوابق -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال والشريحة املستخدمة يف اجلرمية.","document_number":"3427615","case_number":"3432004","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة «الكبتاجون» -إهداء احلبوب احملظورة -تعاطي احلبوب احملظورة -مقاومة قوات الشرطة - إنكار الترويج واالقرار باحليازة والتعاطي -ثبوت اإلدانة بالترويج والبيع واالهداء -تخفيف العقوبة لقلة الكمية ولعدم وجود سوابق -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال والشريحة املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3427615 :‬تاريخه‪1434/2/3 :‬هـ‬\n                         ‫رقم الدعوى‪3432004:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34193166‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة «الكبتاجــون» ‪ -‬إهــداء احلبــوب‬\n      ‫احملظــورة ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬مقاومــة قــوات الشــرطة ‪-‬‬\n      ‫إنــكار الترويــج واالقــرار باحليــازة والتعاطــي ‪ -‬ثبــوت اإلدانــة بالترويــج‬\n      ‫والبيــع واالهــداء ‪ -‬تخفيــف العقوبــة لقلــة الكميــة ولعــدم وجود ســوابق‬\n      ‫‪ -‬تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n                       ‫ومصــادرة اجلــوال والشــريحة املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬والفقــرة (‪)1‬‬\n          ‫مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى عامــة ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات‬\n      ‫احلبــوب احملظــورة الكبتاجــون واإلمفيتامــن ‪ ،‬بقصــد الكســب‬\n      ‫املــادي‪ ،‬مت القبــض علــى املدعــى عليــه وهــو يســلم املصــدر الســري‬\n      ‫حبــوب اإلمفيتامــن‪ ،‬أنكــر املدعــى عليــه صفــة الترويــج وأقــر‬\n      ‫باحليــازة والتعاطــي‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي احتــواء‬\n      ‫املــادة املضبوطــة علــى الكبتاجــون واإلمفيتامــن‪ ،‬طلــب املدعــي العــام‬\n      ‫احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة لقــاء ترويجــه واســتعماله‬\n\n‫‪355‬‬\n\f‫احلبــوب احملظــورة‪ ،‬ومنعــه مــن الســفر إلــى خــارج البــاد بعــد تنفيــذ‬\n‫العقوبــة ومصــادرة اجلــوال املســتخدم يف عمليــة الترويــج وعــدم صــرف‬\n‫الشــريحة لنفــس املســتخدم‪ ،‬وبعقوبــة تعزيريــة بحقــه لقــاء مقاومتــه‬\n‫لرجــال األمــن بقصــد اإلفــات‪ ،‬حكمــت احملكمــة بثبــوت إدانــة‬\n‫املدعــى عليــه بحيــازة احلبــوب احملظــورة بقصــد الترويــج والتعاطــي‪،‬‬\n‫فقــررت احملكمــة احلكــم علــى املدعــى عليــه بســجنه مــدة ســنتني تبــدأ‬\n‫مــن تاريــخ توقيفــه يف هــده القضيــة‪ ،‬وجلــده مائتــي جلــدة مفرقــة علــى‬\n‫دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــرة أيــام‪ ،‬وإلزامــه بدفــع‬\n‫غرامــة ماليــة قدرهــا ألفــا ري ــال‪ ،‬واملنــع مــن الســفر إلــى خــارج البــاد‬\n‫مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة ســجنه‪ ،‬تعزيــره لقــاء الهــروب مــن‬\n‫رجــال األمــن وذلــك بجلــده خمســن جلــدة دفعــة واحــدة‪ ،‬تعزيــره بجلــده‬\n‫خمســن جلــدة دفعــة واحــدة لتعاطيــه احلبوب احملظورة‪ ،‬مصــادرة اجلوال‬\n‫وعــدم صــرف الشــريحة لنفــس املســتخدم‪ ،‬قــرر املدعــى عليــه قناعتــه‬\n   ‫باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ‬\n‫‪1434/01/19‬ه ـ املقيــدة باحملكمة برقم ‪..........‬وتاريخ ‪1434/01/19‬‬\n‫ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/01/21‬ه ـ حضــر املدعــي العــام‪/‬‬\n‫‪..........‬املشــار إلــى خطــاب تكليفــه يف الضبــط وادعــى قائــا دعــواي‬\n‫هــي مــا ورد يف الئحــة الدعــوى العامــة املرفقــة املتضمنــة االدع ــاء علــى‪/‬‬\n\n                                                                                     ‫‪356‬‬\n\f      ‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)..........‬حيــث أنــه‬\n      ‫بتاريــخ ‪1433/11/27‬ه ـ اثــر توفــر معلومــات ملكافحــة املخــدرات‬\n      ‫بخميــس مشــيط مــن أحــد مصادرهــا الســرية عــن قيــام املدعــى عليــه‬\n      ‫بترويــج احلبــوب احملظــورة مت االتصــال علــى جوالــه علــى مســمع مــن‬\n      ‫أفــراد الفرقــة القابضــة ومت طلــب حبــوب محظــورة منــه مببلــغ(‪)250‬‬\n      ‫ريــال فاســتعد بذلــك وطلــب مــن املصــدر احلضــور لــه بحــي ‪..........‬ومت‬\n      ‫تزويدهــم باملبلــغ احلكومــي وتقابلــوا وقــام املدعــى عليــه بتســليم(‪)5‬‬\n      ‫حبــات محظــورة واســتلم املبلــغ احلكومــي وقــام بتســليم أحــد األفــراد‬\n      ‫حبــة محظــورة كإهــداء ومت القبــض عليــه بعــد مقاومــة عنيفــة مــن‬\n      ‫قبلــه بهــدف اإلفــات وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام‬\n      ‫لــه بترويــج عــدد خمــس حبــات مــن احلبــوب احملظــورة عــن طريــق البيــع‬\n      ‫وعــدد حبــة وحــدة عــن طريــق اإلهــداء وبحيــازة ‪ 13‬حبــة بقصــد الترويــج‬\n      ‫واالســتعمال واســتعماله مــن املضبــوط ولنوعــه يف الســابق واملجــرم‬\n      ‫مبوجــب املادة(‪)3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫ومبقاومــة رجــال األمــن بقصــد اإلفــات وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪-1:‬مــا جــاء يف إقــراره املدونــة علــى الصفحــة رقم(‪)3‬مــن ملــف التحقيــق‬\n      ‫املرفــق لفــة رقم(‪-2)12‬مــا ورد يف محضــر ســماع أقوالــه املرفــق علــى‬\n      ‫اللفــة رقم(‪-3)10‬مــا جــاء يف محضــر القبــض والتفتيــش املــدون علــى‬\n      ‫الصفحتــن رقمي(‪)11-2‬مــن ملــف االســتدالل املرفــق علــى لفــة‬\n      ‫رقم(‪-4)1‬مــا ورد يف التقريــر الكيميائــي الشــرعي املرفــق علــى اللفــة‬\n      ‫رقــم(‪ )19‬وبالبحــث عــن ســوابقه اتضــح عدم وجود ســوابق مســجله عليه‬\n      ‫وحيــث أن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه نظامــا‬\n      ‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لــذا أطلــب إثبــات‬\n\n\n‫‪357‬‬\n\f‫مــا أســند إليــه واحلكــم عليــه مبايلي‪-1:‬عقوبــة تعزيريــة بحقــه وفقــا ملــا‬\n‫ورد يف املادة(‪)1/38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫وإعمــال املــادة (‪)62‬مــن النظــام املشــار إليــه بتطبيــق العقوبــة األشــد لقــاء‬\n‫ترويجــه واســتعماله احلبــوب احملظــورة ‪ -2‬منعــه مــن الســفر إلــى خــارج‬\n‫البــاد بعــد تنفيــذ العقوبــة وفقــا ملــا ورد يف املادة(‪)56‬الفقــرة األولــى مــن‬\n‫نظــام مكافحــة املخــدرات املشــار إليــه ‪-3‬مصــادرة اجلــوال ذو الرقــم‬\n‫املصنعــي(‪ )..........‬املســتخدم يف الترويــج اســتنادا للمادة(‪)53‬مــن النظــام‬\n‫املشــار إليــه وإلغــاء الشــريحة رقم(‪)..........‬املســتخدمة يف الترويــج وعــدم‬\n‫صرفــه النفــس املســتخدم اســتنادا لتعميــم وزيــر الداخليــة رقــم (‪)9798‬‬\n‫وتاريــخ ‪1429/2/10-9‬ه ـ ‪-4‬عقوبــة تعزيريــة بحقــه لقــاء مقاومتــه‬\n‫لرجــال األمــن بقصــد اإلفــات هــذه دعــواي وقــد حضــر املدعــى عليــه‬\n‫وبســؤاله اإلجابــة علــى دعــوى املدعــي العــام أجــاب قائــا مــا نســب لــي‬\n‫يف الدعــوى مــن ترويــج احلبــوب احملظــورة فهــذا غيــر صحيــح فلــم أروجها‬\n‫وأمــا مــا نســب لــي مــن حيــازة احلبــوب احملظــورة للتعاطــي وتعاطيهــا فهذا‬\n‫ال وليــس‬  ‫صحيــح وأنــا تائــب إلــى اهلل وأتعهــد بعــدم تكــرار ذلــك مســتقب ً‬\n‫لــي ســوابق هــذه إجابتــي وبســؤال املدعــي العــام عــن بينتــه علــى ترويــج‬\n‫ا بينتــي هــي األدلــة والقرائــن‬  ‫املدعــى عليــه احلبــوب احملظــورة قــرر قائـ ً‬\n                                                       ‫املشــار إليهــا هكــذا قــرر‬\n‫وجــرى اإلطــاع علــى محضــر القبــض املــدون يف امللــف املرفــق لفــة رقــم‬\n‫ـاء علــى ورود معلومــات عــن وجــود شــخص يقــوم‬         ‫(‪ )1‬واملتضمــن أنــه بنـ ً‬\n‫بترويــج احلبــوب احملظــورة عليــه فقــد مت االتصــال علــى املــروج علــى‬\n‫جوالــه رقم(‪)..........‬وطلــب منــه املصــدر حبــوب مقابــل مبلــغ مالــي ووافــق‬\n‫املــروج علــى ذلــك وطلــب احلضــور لــه بحي‪..........‬وقــد جــرى تكليــف‬\n\n\n                                                                                        ‫‪358‬‬\n\f      ‫اثنــن مــن األفــراد مبرافقــة املصــدر وقــد تقابــل املصــدر مــع املــروج يف‬\n      ‫املوقــع املشــار إليــه وقــام بتســليم الفــرد عــدد خمــس حبــات واســتلم منــه‬\n      ‫املبلــغ احلكومــي وقــام بتســليم حبــة واحــدة للفــرد فتــم القبــض عليــه بعــد‬\n      ‫مقاومــة عنيفــة وبتفتيشــه عثــر علــى عــدد ثالثــة عشــرة حبــة مــن احلبــوب‬\n      ‫احملظــورة داخــل كيــس نايلــون كمــا عثــر علــى املبلــغ احلكومــي املرقم‬\n      ‫كمــا عثــر علــى اجلــوال املســتخدم يف عمليــة التنســيق أ‪.‬ه ـ وبعرضــه على‬\n      ‫ا مــا ورد يف محضــر القبــض خــاف إجابتــي على‬          ‫املدعــى عليــه قــرر قائـ ً‬\n      ‫الدعــوى العامــة فهــو غيــر صحيــح والصحيــح ما ذكرتــه يف إجابتي على‬\n      ‫دعــوى املدعــي العــام هكــذا قــرر وقــررت رفــع اجللســة لطلــب معــدي‬\n      ‫محضــر القبــض وأجلــت إلــى يــوم األربعــاء املوافــق ‪1434/01/28‬ه ـ‬\n      ‫ويف اجللســة احملــددة حضــر املدعــي العــام و املدعــى عليــه وقــرر املدعــي‬\n      ‫العــام قائــا مت طلــب معــدي محضــر القبــض بخطابنــا رقــم (‪)23‬‬\n      ‫وتاريــخ ‪1434/01/21‬ه ـ وتعــذر حضورهــم لــذا أطلــب حتديــد موعــد‬\n      ‫جلســة أخــرى لطلبهــم هكــذا قــرر وعليــه قــررت رفــع اجللســة وتأجيلهــا‬\n      ‫إلــى يــوم الســبت املوافــق ‪1434/02/02‬ه ـ ويف اجللســة احملــددة حضــر‬\n      ‫املدعــي العــام واملدعــى عليــه وأحضــر املدعــي العــام للشــهادة كل مــن‬\n      ‫املــدون هويتهمــا وبياناتهمــا يف الضبــط وبســؤالهما عــن مــا لديهمــا مــن‬\n      ‫شــهادة شــهد كل واحــد منهمــا بقولــه أشــهد هلل أنــه قبــل عــدة أشــهر ال‬\n      ‫أذكــر بالتحديــد وردت معلومــات عــن شــخص يقــوم بترويــج احلشــيش‬\n      ‫املخــدر فاتصــل عليــه املصــدر علــى جوالــه وطلــب منــه حبــوب مقابــل‬\n      ‫مائتــن وخمســن ريــاال وقــد انتقلــت مــع املصــدر إلــى حــي ‪..........‬بجــوار‬\n      ‫حديقــة وحضــر املــروج الــذي هــو املدعــى عليه هــذا احلاضر وقــام املدعى‬\n      ‫عليــه بتســليم أحدنــا خمــس حبــات حتمــل عالمــة الكبتاجــون واســتلم‬\n\n\n‫‪359‬‬\n\f‫املبلــغ احلكومــي وقــام بتســليم أحدنــا حبــة واحــدة بــدون مقابــل وركــب‬\n‫الســيارة معنــا وعنــد أســواق ‪..........‬أعطيــت إشــارة القبــض فتــم القبــض‬\n‫علــى املدعــى عليــه وحــن القبــض عليــه حــاول الهــروب وعثــر معــه يف‬\n‫اجليــب العلــوي علــى ثــاث عشــرة حبــة مــن حبــوب الكبتاجــون بداخــل‬\n‫كيــس كمــا عثــر معــه علــى املبلــغ احلكومــي وقــدره مائتــان وخمســون‬\n‫ريــاال كمــا عثــر معــه علــى اجلــوال الــذي جــرى التنســيق معــه بواســطته‬\n‫وقــد جــرى إعــداد محضــر بذلــك هــذه شــهادتي وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــرر قائــا مــا ورد يف شــهادة الشــاهدين خــاف إجابتــي‬\n‫فهــو غيــر صحيــح والصحيــح مــا ذكرتــه يف إجابتــي هكــذا قــرر وجرى‬\n‫تعديــل الشــاهدين مــن قبــل املدونــه ويتهمــا يف الضبــط فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى مــا يلــي ‪-1:‬إنــكار املدعــى عليــه‬\n‫ترويــج احلبــوب احملظــورة واعترافــه بحيازتــه للحبــوب احملظــورة بقصــد‬\n‫التعاطــي وتعاطيهــا ‪-2‬مــا تضمنتــه شــهادة الشــاهدين مــن ترويــج املدعــى‬\n‫عليــه للحبــوب احملظــورة واملعدلــة شــرعا ‪-3‬ترويــج املدعــى عليــه حلبــوب‬\n‫اإلمفيتامــن احملظــورة وحيازتــه لهــا بقصــد الترويــج والتعاطــي فعــل‬\n‫محــرم شــرع ًا ومجــرم نظام ـ ًا ملــا نصــت عليــه الفقــرة الثانيــة مــن املــادة‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومعاقــب عليــه‬\n‫بالعقوبــة األصليــة الــواردة يف املــادة الثامنــة والثالثــن واملــادة الواحــدة‬\n‫واألربعــن والعقوبــة التكميليــة الــواردة يف املــادة السادســة واخلمســن‬\n                                                            ‫مــن النظــام املشــار إليــه‪.‬‬\n‫‪4‬ـ تعاطــي املدعــى عليــه للحبــوب احملظــورة وهــو مكلــف مختــار فعــل‬\n‫محــرم شــرع ًا ومعاقــب عليــه بعقوبــة تعزيريــة ‪5‬ـ ماتضمنــه التقريــر‬\n‫الكيميائــي املشــار إليــه ‪ -6‬عــدم وجــود ســوابق عليه وقلــة الكمية هذا‬\n\n\n                                                                                             ‫‪360‬‬\n\f      ‫كلــه يســتوجب تخفيــف العقوبــة عليــه والنــزول عــن احلــد األدنــى املقــرر‬\n      ‫يف املــادة الثامنــة والثالثــن وفق ـ ًا ملــا ورديف املــادة الســتني مــن النظــام‬\n      ‫املشــار إليــه ‪7‬ـ اســتخدام املدعــى عليــه للجــوال وشــريحة االتصــال املشــار‬\n      ‫إليهــا يف الدعــوى يســتوجب مصادرتــه وفقـ ًا ملــا نصــت عليــه املــادة الثالثــة‬\n      ‫واخلمســن مــن النظــام املذكــور ووفقـ ًا لتعميــم صاحــب الســمو امللكــي‬\n      ‫وزيــر الداخليــة املشــار إليــه ‪-8‬محاولــة املدعــى عليــه الهــروب مــن رجــال‬\n             ‫األمــن أثنــاء القبــض عليــه موجــب لعقوبتــه لــذا فقــد تقــرر مــا يلــي‪:‬‬\n      ‫أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بترويــج عــدد خمــس حبــات مــن‬\n      ‫احلبــوب احملتويــة علــى مــادة اإلمفيتامــن احملظــورة عــن طريــق البيــع‬\n      ‫وإهــداء حبــة وحيــازة ثالثــة عشــر حبــة مــن احلبــوب احملظــورة بقصــد‬\n      ‫الترويــج والتعاطــي وقــررت تعزيــره علــى ذلــك بســجنه مــدة ســنتني تبــدأ‬\n      ‫مــن تاريــخ توقيفــه يف هــذه القضيــة وجلــده مائتــي جلــدة مفرقــة علــى‬\n      ‫دفعــات كل دفعــة خمســون جلــدة وبينهمــا عشــرة أيــام وإلزامــه بدفــع‬\n      ‫غرامــة ماليــة قدرهــا ألفــا ريــال خلزينــة الدولــة ومنعــه مــن الســفر إلــى‬\n      ‫خــارج هــذه البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة ســجنه املنصــوص‬\n      ‫عليهــا أعــاه‪ .‬ثانيـاً‪ :‬ثبــت لــدي اســتخدام املدعــى عليــه للجــوال وشــريحة‬\n      ‫االتصــال املشــار إليهــا وقــررت مصــادرة ذلــك وعــدم صــرف شــريحة‬\n      ‫االتصــال لنفــس املســتخدم‪ .‬ثالثــا ‪ :‬قــررت تعزيــر املدعــى عليــه لقــاء‬\n      ‫محاولــة الهــروب مــن رجــال األمــن وذلــك بجلــده خمســن جلــدة دفعــة‬\n      ‫واحــدة‪ .‬رابعــا ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلبــوب احملظــورة‬\n      ‫وقــررت تعزيــره علــى ذلــك بجلــده خمســن جلــدة دفعــة واحــدة وبذلــك‬\n      ‫حكمــت) وبعــرض احلكــم بعــد اإلضافــة عليــه علــى املدعــي العــام قــرر‬\n      ‫اعتراضــه علــى احلكــم وطلــب رفعــه حملكمــة اإلســتئناف بــدون الئحــة‬\n\n\n‫‪361‬‬\n\f‫اعتراضيــة وبعرضــه علــى املدعــى عليــه قــرر القناعــة بــه وقــررت إعــادة‬\n‫املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                       ‫نبينــا محمــد حــرر يف ‪1434/3/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط‬\n‫املســاعد برقــم ‪ ..........‬وتاريــخ ‪1434/4/3‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪........../‬برقم ‪..........‬وتاريــخ‬\n‫‪1434/2/3‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪........../‬يف قضيــة‬\n‫(مخــدرات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار‬\n‫ـاء علــى قرارنــا رقــم ‪..........‬وتاريــخ ‪1434/2/25‬ه ـ‬  ‫وصــورة ضبطــه بنـ ً‬\n‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                                ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪362‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":355,"source_page_end":362,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8e16ba44aa4256d1d3dda0195da95fbe93a580e20ef60e3f46662627504b274b","normalized_text_hash":"a1fd87a7f45ce9591cc4648db42ef57ec0ae6750336047bee7d777a5217d0bd3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p355-3427615"},{"id":"80583f00-19c5-595a-9ab8-173129351a1d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -حيازة حبوب محظورة -تعاطي احلبوب احملظورة -حيازة املسكر بقصد الترويج والتعاطي -ترويج املسكر -درء احلدود بالشبهات -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة ودفع املبلغ احلكومي.","document_number":"3430850","case_number":"3433546","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/05","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -حيازة حبوب محظورة -تعاطي احلبوب احملظورة -حيازة املسكر بقصد الترويج والتعاطي -ترويج املسكر -درء احلدود بالشبهات -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة ودفع املبلغ احلكومي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3430850:‬تاريخه ‪1434/02/05 :‬هـ‬\n                          ‫رقم الدعوى ‪3433546:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34220469‬تاريخه‪1434/5/22 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة ‪ -‬حيــازة حبــوب محظــورة ‪ -‬تعاطــي‬\n      ‫احلبــوب احملظــورة ‪ -‬حيــازة املســكر بقصــد الترويــج والتعاطــي ‪ -‬ترويــج‬\n      ‫املســكر ‪ -‬درء احلــدود بالشــبهات ‪ -‬التعزيــر بالســجن واجللــد والغرامــة‬\n                          ‫واملنــع مــن الســفر واملصــادرة ودفــع املبلــغ احلكومــي‪.‬‬\n\n\n\n           ‫‪ -1‬قولــه تعالــى ( َو َت َعا َو ُنــوا َع َلــى ا ْل ِبـ ِّـر َوال َّت ْقـ َوى َوال َت َعا َو ُنــوا َع َلــى ْ‬\n      ‫اإلثـ ِـم‬\n                                                                                                                        ‫َوا ْل ُعــدْ َوانِ )‪.‬‬\n      ‫ـاب‬\n      ‫نصـ ُ‬   ‫ال ْمـ ُـر َو ْالَ ْي ِسـ ُـر َوا َأل َ‬\n                                                   ‫نــا ْ َ‬  ‫آم ُنــو ْا ِإ َّ َ‬\n                                                                              ‫‪ -2‬قولــه تعالــى ( َيــا َأ ُّي َهــا ا َّلذِ يـ َـن َ‬\n                   ‫ـوه َل َع َّل ُكـ ْـم ُت ْفل ُِحـ َ‬\n               ‫ـون)‪.‬‬                                 ‫اج َتن ُِبـ ُ‬‫الش ـ ْي َطانِ فَ ْ‬ ‫َوا َأل ْز َال ُم ِر ْ ٌجــس ِّمـ ْـن َع َمــلِ َّ‬\n            ‫‪ -3‬قوله صلى اهلل عليه وسلم (كل مسكر خمر وكل خمر حرام)‪.‬‬\n                         ‫‪ -4‬قوله صلى اهلل عليه وسلم ‪(:‬ادرؤوا احلدود بالشبهات)‪.‬‬\n      ‫‪ -5‬مــن مقاصــد الشــريعة حفــظ الضــرورات اخلمــس ومنهــا حفــظ‬\n                                                                                                                  ‫النفــس والعقــل‪.‬‬\n      ‫‪ -6‬املــواد (‪ )38‬و (‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                                                                           ‫العقليــة‪.‬‬\n                       ‫‪ -7‬تعميم سمو وزير الداخلية رقم ‪ 69935‬يف ‪ 1433/6/18‬هـ‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ببيــع حبــوب اإلمفيتامــن‬\n\n‫‪363‬‬\n\f‫بقصــد االجتــار وحيــازة عــدد مــن حبــوب اإلمفيتامــن بقصــد الترويــج‬\n‫والتعاطــي وحيــازة قواريــر مســكر بقصــد الترويــج والتعاطــي‪ .‬حيــث‬\n‫وردت معلومــات إلدارة مكافحــة املخــدرات عــن قيــام املدعــى عليــه‬\n‫بترويــج حبــوب الكبتاجــون ومت تكليــف أحــد األفــراد باالتصــال علــى‬\n‫املدعــى عليــه وطلــب شــراء احلبــوب احملظــورة ومتــت عمليــة االســتالم‬\n‫والتســليم‪،‬أعطيت اإلشــارة فتــم القبــض علــى املدعــى عليــه وبتفتيشــه‬\n‫عثــر معــه علــى املبلــغ املرقــم كمــا ضبــط معــه جــوال آخــر غيــر الــذي‬\n‫نســق عليه‪،‬وبتفتيــش ســيارته عثــر علــى عــدد مــن حبــوب اإلمفيتامــن‬\n‫وعبــوات خمــر ومبلــغ مالــي وطلــب املدعــي العــام إثبات ما أســند للمدعى‬\n‫عليــه واحلكــم عليــه وفــق نظــام مكافحــة املخــدرات وتعزيــره لقــاء‬\n‫حيازتــه للمســكر‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه وأنكــر شــرب‬\n‫املســكر ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن‬\n‫واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة ودفــع املبلــغ احلكومــي‬\n                               ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬     ‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬يف احملكمــة اجلزائيــة مبحافظــة‬\n‫‪ ......‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمــة اجلزائية‬\n‫يف محافظــة ‪/......‬املســاعد برقــم ‪ ......‬وتاريــخ ‪ ......‬املقيــدة باحملكمــة‬\n‫برقــم ‪ ......‬وتاريــخ ‪ ......‬ففــي يــوم األربعــاء ‪ ......‬افتتحــت اجللســة الســاعة‬\n‫‪ 08 : 30‬وفيهــا حضــر املدعــي العــام ‪ ......‬نيابــة عــن املدعــي العــام ‪......‬‬\n‫واملكلــف مــن هيئــة التحقيــق واالدعــاء العــام مبوجــب أمــر التكليــف‬\n‫رقــم ‪ ......‬وتاريــخ ‪ ......‬وادعــى علــى احلاضــر معــه يف مجلــس احلكم ‪،......‬‬\n\n                                                                                         ‫‪364‬‬\n\f      ‫(‪ )......‬عامـاً‪ ،‬ســعودي اجلنسي ــة‪ ،‬مبوجــب الســجل املدنــي رقــم ( ‪،)......‬‬\n      ‫موقــوف بالســجن العــام مبحافظــة ‪ ......‬مبوجــب أمــر متديــد التوقيــف‬\n      ‫رقــم(‪ )...... 0‬وتاريــخ ‪ ، ......‬اســتنادا للقــرار الــوزاري رقــم( ‪ )1900‬وتاريخ‬\n      ‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫ا يف حتريــر دعــواه إنــه بتاريــخ ‪ ......‬قبــض علــى املذكــور أعــاه‬         ‫قائ ـ ً‬\n      ‫بتاريــخ ‪ ......‬بنــاء علــى إخباريــة أحــد متعاونــي الفرقــة عــن معرفتــه‬\n      ‫لشــخص يدعــى‪ ، ....../‬ســعودي اجلنســية ‪ ،‬يســتخدم اجلــوال ذو الرقــم‬\n      ‫(‪ ) ......‬يبيــع حبــوب الكبتاجــون يف ‪ ....‬وال يســتطع الشــراء املباشــر‬\n      ‫منــه‪ ،‬عليــه مت تكليــف أحــد أفــراد الفرقــة مبهمــة االتصــال باملعنــي‬\n      ‫وحتــدث معــه حيــال رغبتــه يف شــراء كميــة مــن احلبــوب مببلــغ مئتــي‬\n      ‫ريــال فوافــق املعنــي وطلــب مــن الفــرد أن يقابلــه بجــوار أحــد املســاجد‬\n      ‫ببدايــة طريــق ‪. .....‬ونظــر ًا لتعــذر تأمــن كامــل املبلــغ يف حينــه تقــرر‬\n      ‫الشــراء مببلــغ مائــة ريــال وبعــد ترقيــم املبلــغ مت االنتقــال للموقــع املتفــق‬\n      ‫عليــه وبــه حضــر املعنــي يقــود ســيارة مــن نــوع ‪ .....‬حتمل لوحة رقــم ( ‪)......‬‬\n      ‫موديــل ‪ ......‬ويرافقــه شــخصان وحضــر اليــه الفــرد وحتــدث معــه مــن باب‬\n      ‫الســائق وســلم لــه الفــرد مبلــغ مائــة ريــال وطلــب منــه بهــذا املبلــغ فقــط‬\n      ‫فســلم للفــرد عــدد أربــع حبــات يشــتبه أن تكــون مؤثــرة عقليـ ًا وحتــول‬\n      ‫مــن املوقــع ونظــر ًا لظــروف املوقــع وصعوبــة متابعتــه فتقــرر تركــه لوقــت‬\n      ‫آخــر والشــراء منــه مــرة أخــرى ويف يــوم األحــد املوافــق ‪ ......‬ويف متــام‬\n      ‫الســاعة الثانيــة عشــر والنصــف ظهــر ًا أتصــل الفــرد ممثــل دور املشــتري‬\n      ‫باملعنــي مــرة أخــرى وطلــب منــه شــراء كميــة مببلــغ مئتــي ريــال فوافــق‬\n      ‫وطلــب مــن الفــرد أن يقابلــه بجــوار قاعــة ‪ ....‬بحــي ‪ ....‬وعليــه مت تكليــف‬\n      ‫الفــرد بالشــراء و ترقيــم املبلــغ وبعــد الوصــول للموقــع مت االتصــال‬\n\n\n‫‪365‬‬\n\f‫باملعنــي وإبالغــه بالتواجــد فطلــب احلضــور لــه بجــوار إحــدى محطــات‬\n‫احملروقــات ومت االنتقــال لهــذا املوقــع وعنــد وصولــه وجــد املعنــي بجــوار‬\n‫الســيارة التــي حضــر عليهــا املــرة األولــى وحضــر للفــرد وســأله بكــم‬\n‫تريــد وعندمــا أراد الفــرد تســليمه املبلــغ لــم يجــد معــه إال مبلــغ مائــة‬\n‫ريــال مــن املبلــغ املرقــم فطلــب منــه مببلــغ مائــة ريــال فقــط فســلمه أربــع‬\n‫حبــات بيجيــة اللــون يشــتبه أن تكــون مــن احلبــوب احملظــورة ثــم أعطيــت‬\n‫اإلشــارة لتمــام عمليــة الشــراء فتــم القبــض عليــه واتضــح بأنــه املذكــور‬\n‫أعــاه وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى شــيء مــن املمنوعــات‬\n‫وضبــط يف جيــب بنطالــه األميــن املبلــغ املرقــم الثانــي ولــم يعثــر علــى‬\n‫املبلــغ املرقــم األول وضبــط معــه جوالــن أحدهمــا الــذى مت التنســيق‬\n‫عليــه وبتفتيــش الســيارة ضبــط يف درج صغيــر بجــوار ناقــل احلركــة مــن‬\n‫األمــام كيــس نايلــون بــه خمــس وســتون حبــة بيجيــة اللــون يشــتبه أن‬\n‫تكــون مــن احلبــوب احملظــورة وضبــط يف شــنطة الســيارة كيــس نايلــون‬\n‫بــه خمســة عبــوات بالســتيكية مــاء كبيــرة بــكل منهــا ســائل شــفاف‬\n‫كريــه الرائحــة يشــتبه أن يكــون العــرق املســكر وضبــط معــه مبلــغ‬\n‫مالــي قــدره ثالثــة وتســعون ريــال فقــط ومبناقشــته عــن املصــدر الــذى‬\n‫يحصــل منــه علــى احلبــوب ذكــر أنــه يحصــل عليهــا مــن شــخص يدعــى‬\n‫‪ ....‬اســتعد باإلطاحــة بــه والشــراء املباشــر منــه وقــد مت ذلــك بالفعــل‬\n‫وقبــض عليــه باجلــرم املشــهود بالقضيــة رقــم (‪ . ) ......‬وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم ( ‪ ) ......‬لعــام ‪ ......‬احتــواء كامــل الكميــة‬\n‫املشــتراة املرمــز لهــا بالرمــز (أ) وكامــل الكميــة املشــتراة املرمــز لهــا‬\n‫بالرمــز (ب) والعينــة (ج) مــن الكميــة املضبوطــة واملرســلة للتحليــل ملــادة‬\n‫االمفيتامــن املؤثــرة عقليـ ًا واملــدرج بجــدول املخــدرات رقــم (‪ )2‬فئــة (ب)‬\n\n\n                                                                                        ‫‪366‬‬\n\f      ‫امللحــق بنظــام مكافحــة املخــدرات واحتــواء العينــة (د) مــن الســائل‬\n      ‫املضبــوط علــى الكحــول االيثيلــي املســكر وقــدرت نســبته بــ(‪)% 46.1‬‬\n      ‫باســتجواب املدعــى عليــه ‪ ، ......‬بعــد إحاطتــه علم ـ ًا بالتهمــة املنســوبة‬\n      ‫إليــه أقــر ببيــع أربــع حبــات مــن حبــوب الكبتاجــون املؤثــرة عقليـ ًا بتاريــخ‬\n      ‫‪ ......‬وبيــع أربــع حبــات أخــرى مــن نوعهــا بتاريــخ ‪ ......‬وبترويجــه حلبــوب‬\n      ‫الكبتاجــون منــذ ثالثــة أســابيع وبحيازتــه لعــدد ( ‪ ) 65‬حبــه أخــرى مــن‬\n      ‫نوعهــا بقصــد الترويــج والتعاطــي وتعاطيــه مــن ذات الكميــة ولنوعهــا‬\n      ‫ســابق ًا كمــا أقــر بحيازتــه لعــدد خمســة قواريــر مــاء كبيــرة مملــوءة‬\n      ‫بســائل العــرق املســكر بقصــد الترويــج والتعاطــي وبترويجــه وبتعاطيــه‬\n      ‫للعــرق املســكر منــذ ســتة أشــهر تقريب ـ ًا وافــاد بعــدم عالقــة أو علــم‬\n      ‫صاحــب الســيارة املدعــو ‪ ......‬بالكميــة املضبوطــة وكذلــك عمليتــي‬\n      ‫الترويــج وبــان ســبب تواجــد ســيارته معــه لغــرض التجربة متهيد ًا لشــرائها‬\n      ‫كمــا أفــاد بــأن الشــخصان اللــذان كانــا يرافقانــه يف عمليــة الترويــج‬\n      ‫األولــى ال تربطــه بهمــا عالقــة وال يعلمــان عــن الكميــة املباعــة وبأنــه قام‬\n      ‫بإركابهمــا مــن محطــة ‪ ....‬وال يعرفهمــا وأخبرهمــا برغبتــه يف مقابلــة‬\n      ‫شــقيقه ألخــذ مبلــغ مــن املــال منــه كمــا أفــاد بأنــه أثنــاء تفتيــش ســيارته‬\n      ‫مــن قبــل أفــراد الفرقــة فقــد مبلــغ مالــي وقــدره ( ‪ ) 1500‬ريــال كان يف‬\n                                                     ‫درج الســيارة ويتهمهــم يف أخــذه ‪.‬‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام إلــي ‪ ، ......‬ببيــع ( ‪ ) 8‬حبــات‬\n      ‫مــن حبــوب حتتــوي علــى مــادة االمفيتامــن املؤثــرة عقليـ ًا بقصــد االجتــار‬\n      ‫وحيــازة عــدد( ‪ ) 65‬مــن نوعهــا بقصــد الترويــج والتعاطــي وتعاطيــه مــن‬\n      ‫ذات الكميــة ولنوعهــا ســابق ًا وترويجــه لنوعهــا ســابق ًا ‪،‬اســتناد ًا للفقــرة‬\n      ‫( ‪ ) 2‬مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقلية‬\n\n\n‫‪367‬‬\n\f‫‪ ،‬وبحيــازة عــدد ( ‪ ) 5‬قواريــر مــاء كبيــرة مملــؤة بســائل املســكر‬\n‫بقصــد الترويــج و التعاطــي و ترويجــه وشــربه لنوعــه ســابق ًا ‪ ،‬وذلــك‬\n                                                           ‫لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ .1‬مــا ورد يف اعترافــات املذكــور املنــوه عنهــا املدونــة علــى الصفحــات‬\n                                                                   ‫املرفقــة رقــم (‪)......‬‬\n‫ا املرفــق لفــة‬‫‪ .2‬مــا ورد مبحضــر الضبــط والتفتيــش املنــوه عنــه تفصي ـ ً‬\n                                                                                   ‫(‪.)1‬‬\n     ‫‪ .3‬ما ورد بالتقرير الكيميائي الشرعي املنوه عنه املرفق لفة ( ‪. ) 26‬‬\n‫وباالطــاع علــى ســوابقه عثــر لــه علــى ســابق ( شــرب وحيــازة املســكرات )‬\n                                                                          ‫مســجله عليــه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫مــن األفعــال احملرمــة شــرع ًا واملجرمــة شــرع ًا ونظام ـ ًا طبق ـ ًا للمــادة‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ ) 39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬واملعاقــب‬\n‫عليهــا اســتناد ًا للمادتــن ( ‪ ) 41 ، 38‬مــع مراعــاة مــا ورد يف املــادة (‪)62‬‬\n‫مــن ذات النظــام ‪ ،‬لــذا اطلــب إثبــات مــا أســند إليــه ومعاقبتــه بالعقوبــة‬\n                                                  ‫األصليــة والتكميليــة التاليــة ‪.‬‬\n‫‪-1‬بالســجن واجللــد والغرامــة لقــاء مــا أســند اليــه اســتناد ًا للفقــرة ( ‪) 1‬‬\n‫مــع تشــديد العقوبــة وفق ـ ًا للحالــة ( ج ) مــن الفقــرة الثانيــة مــن املــادة‬\n‫( ‪ ) 38‬مــن نظــام مكافحــة املخــدرات املشــار إليــه اســتناد ًا لتعميــم‬\n   ‫وزيــر الداخليــة رقــم ( ‪/8346/4/5/1‬ش ) وتاريــخ ‪1427/2/8‬ه ـ ‪.‬‬\n‫‪-2‬مصــادرة جهــازه الهاتــف اجلــوال مــن نــوع ( ‪ ) ......‬ذي الرقــم املصنعــي‬\n‫(‪ )......‬املســتخدم يف ارتــكاب اجلرميــة اســتناد ًا للفقــرة ( ‪ ) 1‬مــن املــادة‬\n\n\n                                                                                              ‫‪368‬‬\n\f      ‫(‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه وإلغــاء اخلدمــة عــن‬\n      ‫الشــريحة وعــدم صرفهــا ملــن أســاء اســتخدامها اســتناد ًا لبرقيــة صاحــب‬\n         ‫الســمو امللكــي وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10-9‬ه ـ ‪.‬‬\n      ‫‪-3‬منعــه مــن الســفر خــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهمــا‬\n      ‫اســتناد ًا للفقــرة ( ‪ ) 1‬مــن املــادة ( ‪ ) 56‬مــن نظــام مكافحــة املخــدرات‬\n                                                                            ‫املشــار إليــه ‪.‬‬\n      ‫‪-4‬كمــا أطلــب إلزامــه بإعــادة املبلــغ املرقــم املفقــود املقــدر ب ـ (‪)100‬‬\n      ‫مائــة ريــال ملكافحــة املخــدرات مبحافظــة جــدة اســتنادا إلــى تعميــم‬\n      ‫ســمو وزيــر الداخليــة رقــم ( ‪ ) 29290/4/5/1‬يف ‪1431/5/7‬هـ‪.‬كمــا‬\n                                ‫أطلــب إقامــة حــد املســكر بحقــه لقــاء شــربه لــه‪.‬‬\n      ‫كمــا أطلــب عقوبــة تعزيريــة بحقــه لقــاء حيازتــه لعــدد ( ‪ ) 5‬خمســة‬\n      ‫قواريــر مملــؤة بالســائل املســكر بقصــد الترويــج والتعاطــي وترويجــه‬\n                                        ‫لنوعــه ســابق ًا هــذه دعــواي وأســاله اجلــواب‬\n      ‫ال كل ما ذكره املدعي‬            ‫وبســؤال املدعى عليه عن الدعوى أجاب قائ ً‬\n      ‫ا فقــد قبــض علـ ّـي مــن قبــل مكافحــة‬         ‫العــام صحيــح جملــة وتفصي ـ ً‬\n      ‫املخــدرات بتاريــخ ‪ ......‬بعــد التنســيق معــي عبــر جوالــي ذي الرقــم ( ‪)......‬‬\n      ‫لقيامــي‪ ،‬ببيــع ثمانيــة حبــات مــن حبــوب الكبتاجــون املؤثــرة عقليـ ًا وقــد‬\n      ‫قمــت ببيــع ذلــك مببلــغ ( ‪ ) 300‬ثالثمائــة ريــال وحيازتــي لعــدد ( ‪)65‬‬\n      ‫مــن نوعهــا بقصــد الترويــج والتعاطــي وحيازتــي لعــدد ( ‪ ) 5‬قواريــر‬\n      ‫مــاء كبيــرة مملــؤه بســائل املســكر بقصــد الترويــج وترويجــه ســابق ًا‬\n      ‫فصحيــح ومــا ذكــره املدعــي العــام مــن أننــي قــد تعاطيــت منــه ولنوعــه‬\n      ‫ســابقا فذلــك صحيــح وقــد حوكمــت لقــاء ذلــك عــام ‪ 000‬قبــل ثمانيــة‬\n      ‫أشــهر وبعدهــا تبــت إلــى اهلل ولــم أشــرب بعدهــا املســكر ومــا ذكــره‬\n\n\n‫‪369‬‬\n\f‫املدعــي العــام مــن وجــود عــدد ســابقة يف شــرب وحيــازة املســكرات‬\n‫مســجلة علـ ّـي فذلــك صحيــح أيضـ ًا وقــد أقدمــت علــى ذلــك وأنــا مســلم‬\n‫وأعلــم بــان ذلــك محــرم شــرع ًا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى‬\n‫هــذا الفعــل وأتعهــد بصــدق بعــدم العــودة لفعلــي هكــذا أجــاب وبســؤال‬\n‫املدعــى العــام عــن بينتــه علــى شــرب املدعــى عليــه للعــرق املســكر‬\n‫بعــد احلكــم عليــه بشــربه ســابقا قــال بينتــي مــا جــاء يف أوراق املعاملــة‬\n‫مــن أدلــة وقرائــن هــذا وقــد جــرى اطالعــي علــى أوراق املعاملــة وعلــى‬\n‫تقريــر الســموم والكحــول رقــم (‪ ) ......‬املرفــق باملعاملــة لفــة رقــم (‪)26‬‬\n‫ويتضمن إيجابية احتواء العينة للكحول بنسبة (‪ )% 46.1‬وعلى التقرير‬\n‫الكيميائــي الشــرعي رقــم (‪ )......‬املرفــق باملعاملــة لفــة رقــم (‪)26‬‬\n‫ويتضمــن إيجابيــة احتــواء العينــة لالمفيتامــن املؤثــر عقليــا كمــا جــرى‬\n‫اطالعــي علــى صحيفــة ســوابق املدعــى عليــه املرفقــة باملعاملــة باللفــة‬\n‫رقــم (‪ )23‬املتضمنــة وجــود عــدد ســابقه يف شــرب وحيــازة املســكرات‬\n‫بتاريــخ ‪ ......‬مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى‬\n‫اقــوال املدعــى عليــه املرفقــة باملعاملــة لفــة رقــم (‪ )17‬واملتضمنــة مــا نصــه‬\n‫س‪ /‬متــى آخــر مــرة قمــت فيهــا بشــرب العــرق املســكر ج ‪ /‬قبــل أســبوع‬\n‫تقريبــا وبســؤاله عــن هــذا قــال إننــي بصمــت عليهــا وكان قصــدي بهــا‬\n‫قبــل ســتة أشــهر هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومــا قــرره الطرفــان وملصادقــة املدعــى عليــه علــى جميــع‬\n‫دعــوى املدعــي العــام وإنــكاره شــربه للمســكر بعدمــا حــد فيــه ســابق ًا‬\n‫وإلقــراره حتقيق ـ ًا وإنــكاره للشــرب يف مجلــس احلكــم ورجوعــي عــن‬\n‫إقــراره شــبهة تــدار بهــا احلــدود وملــا تضمنــه تقريــر الســموم والكحــول‬\n‫فقــد ثبــت لــدي إدانــة املدعــى عليــه املذكــور بعاليــه مبــا نســب إليــه مــن‬\n\n\n                                                                                        ‫‪370‬‬\n\f      ‫قيامــه بترويــج ثمانيــة حبــات مــن حبــوب الكبتاجــون املؤثــرة عقلي ـ ًا‬\n      ‫مببلــغ (‪ ) 300‬ثالثمائــة ريــال بقصــد االجتــار كمــا ثبــت لــدي حيازتــه‬\n      ‫لعــدد ( ‪ ) 65‬حبــه مــن ذات النــوع بقصــد الترويــج والتعاطــي كمــا ثبــت‬\n      ‫لــدي حيازتــه لعــدد ( ‪ ) 5‬قواريــر مــاء كبيــرة مملــؤة بســائل املســكر‬\n      ‫بقصــد الترويــج و التعاطــي و ترويجــه ســابقا كمــا لــم يثبــت لــدى تعاطي‬\n      ‫املدعــى عليــه للعــرق املســكر أال أن الشــبهة تتجــه نحــوه بذلــك ومبــا أن‬\n      ‫قبيحــا وجــرأة يف‬\n                       ‫ً‬     ‫ا‬‫محرمــا وفع ـ ً‬\n                                         ‫ً‬     ‫ا‬‫مــا قــام بــه املدعــى عليــه يعــد عم ـ ً‬\n      ‫الباطــل يســتحق العقــاب عليــه ومبــا أن ترويــج ذلــك فيــه نشــر للفســاد‬\n      ‫أوســاط املجتمــع وهــو مــن التعــاون علــى اإلثم والعــدوان واهلل تعالى يقول‬\n      ‫(وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم والعــدوان) وملــا يف‬\n      ‫تعاطــي املســكر مــن املخالفــة لنــص القــران الكــرمي فــاهلل تعالــى يقــول‬\n      ‫( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس‬\n      ‫مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقــول النبــي صلــى‬\n      ‫اهلل عليــه وســلم (كل مســكر خمــر وكل خمــر حــرام) ولقولــه صلــى‬\n      ‫اهلل عليــه وســلم (ادرؤوا احلــدود بالشــبهات) وملــا يف تعاطــي ذلــك مــن‬\n      ‫إضــرار بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا والشــريعة‬\n      ‫اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ النفــس‬\n      ‫والعقــل والنتشــار هــذه احملظــورات أوســاط املجتمــع وهــذا يســتوجب‬\n      ‫األخــذ علــى مــن يقــوم بترويجهــا وتعاطيهــا بحــزم وتطبيــق املــادة رقــم‬\n      ‫(‪ )38‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ومبــا أن املدعــى عليــه‬\n      ‫أظهــر التوبــة والنــدم والعــزم علــى عــدم العــودة لفعلــه ولقلــة الســوابق‬\n      ‫املســجلة عليــه ونظــرا لقلــة الكميــة التــي بحوزتــه وهــذا يخفــف عنــه‬\n      ‫العقوبــة وفقــا للمــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات املشــار‬\n\n\n‫‪371‬‬\n\f‫إليــه وذلــك كلــه أمــر يلحــظ ولكــون املدعــى عليــه يســتحق العقوبــة‬\n‫ووفقــا للمادتــن (‪ )56 -60‬مــن نظام مكافحة‬          ‫طبقــا للقواعــد الشــرعية ً‬  ‫ً‬\n‫املخــدرات فلمــا ســبق فقــد حكمــت علــى املدعــى عليــه مبــا يلــي‪ :‬أوالً‪:‬‬\n‫يجلــد املدعــى عليــه ســبعون جلــدة دفعــة واحــدة أمــام ملــئ مــن النــاس‬\n‫لقــاء االشــتباه بــه يف شــربه املســكر تعزيــرا لــه ثاني ـاً‪ :‬يســجن املدعــى‬\n‫موقوفــا يف هــذه القضيــة‬ ‫ً‬      ‫عليــه ملــدة ســنتني يحتســب منهــا مــا أمضــاه‬\n‫ويجلــد خمســون جلــدة مكــررة عليــه ســتبني كل مــرة وأخــرى مــدة ال‬\n‫تقــل عــن خمســة عشــر يومــا ويدفــع غرامــة ماليــة قدرهــا خمســة االف‬\n‫ريــال وفقــا للمــادة رقــم (‪ )60‬مــن النظــام املشــار إليــه املتضمنــة حــق‬\n‫النــزول عــن مقتضــى املــادة رقــم (‪ )38‬مــن النظــام املشــار إليــه‪ .‬ثالث ـاً‪:‬‬\n‫يســجن املدعــى عليــه ملــدة ثمانيــة أشــهر وذلــك بعــد انتهــاء احلبس الســابق‬\n‫ويجلــد خمســون جلــدة مكــررة عليــه ســت مــرات بــن كل مــرة وأخــرى‬\n‫مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بينــه وبــن اجللــد الســابق‬\n‫مــدة ال تقــل عــن خمســة عشــر يومــا لقــاء ترويجــه للمســكر وترويجــه‬\n                                                                       ‫لنوعــه ســابقا‪.‬‬\n‫رابعــا‪ :‬مينــع املدعــى عليــه مــن الســفر خــارج اململكــة بعــد انتهــاء تنفيــذ‬\n‫محكوميتــه ملــدة ســنتني وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن‬\n                                        ‫نظــام مكافحــة املخــدرات املشــار إليــه‪.‬‬\n‫خامســا‪ :‬مصــادرة الهاتــف اجلــوال للمدعــى عليــه وشــريحته املســتخدمني‬\n‫يف عمليــة الترويــج وعــدم صــرف الشــريحة لــه مــرة أخــرى تعزيــر ًا لــه‬\n‫لســوء اســتخدامه لهــا سادســا‪ :‬يدفــع املدعــى عليــه مبلــغ مائــة ريــال‬\n‫ل ــمكافحة املخــدرات عوض ـ ًا عــن املبلــغ املالــي املرقــم املســتخدم يف‬\n‫عمليــة الترويــج وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n\n\n                                                                                          ‫‪372‬‬\n\f      ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n      ‫باحلضــور يف يــوم الســبت املوافــق ‪ ......‬الســتالم نســخة مــن قــرار احلكــم‬\n      ‫لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يومــا اعتبــار ًا مــن التاريــخ‬\n      ‫املشــار إليــه فــان مضــت املــدة ولــم يســتلم نســخة مــن احلكــم أو لــم يقــدم‬\n      ‫اعتراضــه عليــه خاللهــا فــان حقــه يف تقــدمي الئحــة االعتــراض يكــون‬\n      ‫ســاقط ًا كمــا قــرر املدعــى عليــه قناعتــه بــه وجــرى النطــق باحلكــم يف‬\n      ‫يــوم االربعــاء املوافــق ‪ ......‬الســاعة التاســعة وبــه أقفلــت اجللســة وعلــى‬\n      ‫ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي أن‬\n      ‫‪ ......‬القاضــي باحملكمــة اجلزائيــة ‪ ......‬وبعــد ورود الالئحــة االعتراضيــة‬\n      ‫مــن املدعــي العــام املتعلقــة بدعــواه ضــد ‪ ......‬املكونــة مــن أربــع صفحــات‬\n      ‫وبعــد االطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه‬\n      ‫وقــررت رفــع املعاملــة مــع القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫حملكمــة االســتئناف ‪ ......‬لتدقيــق احلكــم كاملتبــع وعليــه حصــل‬\n      ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                        ‫وصحبــه أجمعــن حــرر يف ‪......‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف يف‬\n      ‫منطقــة ‪ ......‬االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة ‪ ......‬املســاعد برقــم ‪ ......‬وتاريــخ ‪ ......‬املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ ....../‬القاضــي باحملكمــة اجلزائيــة ‪ ......‬برقــم‬\n      ‫‪ ......‬وتاريــخ ‪ ......‬املتضمــن دعــوى املدعــي العــام ضــد‪ ، ....../‬املتهــم‬\n      ‫يف مخــدرات احملكــوم فيــه مبــا دون باطــن القــرار ‪.‬وبدراســة القــرار‬\n\n\n‫‪373‬‬\n\f‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪374‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":363,"source_page_end":374,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a44c7c1379812f2df909eafa62d77b7ebf291622e99f707b1d8e511e3c93ae2d","normalized_text_hash":"04b805076100f335b138b9434f73485ce7fa483c1b6ee333d0c54d6f544bd2b4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p363-3430850"},{"id":"b5290663-7681-5631-8297-424e330b26f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج عن طريق النقل -قات -االشتراك يف الترويج -الكمية املضبوطة قليلة -النزول عن احلد األدنى للعقوبة - التعزير بالسجن والغرامة واملنع من السفر .","document_number":"3422247","case_number":"3434976","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/25","year":"1434","subject":"مخدرات -ترويج عن طريق النقل -قات -االشتراك يف الترويج -الكمية املضبوطة قليلة -النزول عن احلد األدنى للعقوبة - التعزير بالسجن والغرامة واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3422247 :‬تاريخه ‪1434/1/25 :‬هـ‬\n                          ‫رقم الدعوى‪3434976:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34188509‬تاريخه‪1434/04/15 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج عــن طريــق النقــل ‪ -‬قــات ‪ -‬االشــتراك يف الترويــج‬\n      ‫‪ -‬الكميــة املضبوطــة قليلــة ‪ -‬النــزول عــن احلــد األدنــى للعقوبــة ‪-‬‬\n                          ‫التعزيــر بالســجن والغرامــة واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374‬ه ـ املعــدل‬\n      ‫بقــراري وزيــر الداخليــة رقــم (‪ )2057‬لعــام ‪1404‬ه ـ ورقــم (‪)3818‬‬\n                                                                      ‫لعام‪1410‬هــ‪.‬‬\n      ‫‪ -2‬األمــر الســامي الكــرمي رقــم (‪ )59633‬يف ‪1433/12/9‬ه ـ القاضــي‬\n         ‫باســتثناء عقوبــات قضايــا القــات مــن نظــام مكافحــة املخــدرات‬\n                          ‫‪ -3‬تعميم وزير الداخلية (‪ )69935‬يف ‪1433/6/18‬هـ‬\n\n\n\n\n      ‫الئحــة دعــوى عامــة ضــد املدعــى عليــه األول بترويــج قــات عــن طريــق‬\n      ‫النقــل وضــد الثانــي باالشــتراك يف نقــل القــات ‪،‬املدعــى عليهمــا يقومــان‬\n      ‫بنقــل القــات مــن مــكان إلــى آخر ومت القبض علــى املدعى عليهما داخل‬\n      ‫أحــد األحــواش املهجــورة وبتفتيــش الســيارة مت العثــور علــى نبــات أخضــر‬\n      ‫يشــتبه بنبــات القــات وطلــب إثبــات مــا أســند إليهمــا وتعزيرهمــا ومنعهمــا‬\n      ‫مــن الســفر ومصــادرة الســيارة املســتخدمة يف اجلرميــة وأثبــت التقريــر‬\n\n‫‪375‬‬\n\f‫الكيمائــي الشــرعي إيجابيــة العينــة لنبــات القــات احملظــور ‪،‬وصــادق‬\n‫املدعــى عليهمــا علــى الدعــوى ‪،‬قــررت احملكمــة النــزول عــن احلــد‬\n‫األدنــى للعقوبــة املقــرر يف املــادة الثالثــة لصغــر حجــم الكميــة وقناعــة‬\n‫احملكمــة بظروفهمــا االجتماعيــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بتعزيــر املدعــى عليهمــا بســجنهما ســتة أشــهر وغرامــة ماليــة‬\n‫قدرهــا ألــف ريــال علــى كل واحــد منهمــا ومنعهمــا مــن الســفر وصــرف‬\n‫النظــر عــن مصــادرة الســيارة وبعــد احلكــم عليهمــا قنــع املدعــى عليهمــا‬\n‫‪،‬وصــدق‬‫ُ‬     ‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة اعتراضيــة‬\n                                        ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بجــازان برقــم ‪ 3434976‬وتاريــخ ‪ 1434/01/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34170009‬وتاريــخ ‪ 1434/01/20‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/01/25‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪: 00‬‬\n‫‪ 11‬وفيهــا حضــر املدعــي العــام ‪ ..... /‬املوجــه باخلطــاب رقــم (‪ ).....‬يف‬\n‫‪1433/3/22‬ه ـ وأدعــى علــى احلاضريــن معــه الســجناء‪( ..... /1‬ســعودي‬\n‫) اجلنســية مبوجب الســجل املدني رقم ( ‪(..... /2 ).....‬ســعودي ) اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه مــن يــوم االثنــن املوافــق‬\n‫‪1433/11/22‬ه ـ وأثنــاء قيــام إحــدى دوريــات مكافحــة املخــدرات‬\n‫ـاء علــى املعلومــات املتوفــرة عــن قيــام صاحــب ســيارة‬‫بعملهــا امليدانــي وبنـ ً‬\n‫مــن نــوع ‪ ....‬موديــل ‪2003‬م باللوحــة رقــم(‪( ).....‬كانــت بقيــادة املدعــى‬\n\n                                                                                        ‫‪376‬‬\n\f      ‫عليــه ‪).....‬بنقــل نبــات القــات مــن محافظــة الدائــر إلــى قريــة ‪.....‬التابعــة‬\n      ‫صباحــا ُشــوهدت الســيارة‬  ‫ً‬        ‫حملافظــة صبيــا ويف متــام الســاعة الســابعة‬\n      ‫يســتقلها شــخصان وقامــت بالدخــول إلــى أحــد األحواش املهجــورة بقرية‬\n      ‫‪.....‬وبعــد التأكــد مــن هــذه الســيارة محملــة بنبــات القــات ومتوقفــة‬\n      ‫داخــل احلــوش وبجانبهــا ســيارة أخــرى فتــم التوجــه إليهــم ومباغتتهــم‬\n      ‫وإغــاق بوابــة احلــوش وبتفتيــش الســيارة عثــر بداخلهــا علــى كميــة‬\n      ‫مــن نبــات أخضــر يشــتبه أن يكــون مــن نبــات القــات احملظــور وقــد بلــغ‬\n      ‫وزنهــا (‪7,13‬كجــم) ســبعة كيلــو وثالثــة عشــر جرامـ ًا ‪ ،‬أثبــت الت ــقرير‬\n      ‫الكيميائــي الشـ ــرعي رق ـ ـ ــم (‪.....‬و تاريــخ ‪1433/11/30‬هــ) الصــادر‬\n      ‫مــن ‪ ....‬إيجابيــة العينــة املرســلة منــه لنبــات القــات احملظــور املــدرج علــى‬\n      ‫اجلــدول رقــم(‪ )4‬واجلــدول رقــم (‪ )2‬فئــة (أ)و(ج) امللحــق بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م ‪39/‬‬\n      ‫وتاريــخ ‪1426/7/8‬ه ـ ‪.‬باســتجواب املدعــى عليــه األول‪...../‬ومواجهتــه‬\n      ‫بالتهــم املنســوبة إليــه أقــر بحيازتــه للكميــة املضبوطــة ‪،‬وأنــه يقــوم‬\n      ‫بنقــل نبــات القــات مــن قريــة ‪.....‬التابعــة ل ـ ‪ ........‬إلــى قريــة ‪.....‬التابعــة‬\n      ‫حملافظــة ‪ ........‬لشــخص ســعودي يدعــى‪ ...../‬أســمر البشــرة يف العقــد‬\n      ‫اخلامــس مــن عمــره متوســط الطــول والبنيــة وأن أخيــه املدعــو‪...../‬كان‬\n      ‫برفقتــه ويعلــم عــن الكميــة املضبوطــة‪ ،‬واســتؤجر علــى نقلهــا مببلــغ‬\n      ‫وقــدره (‪3000‬ريال)ثالثــة أالف ريــال ‪،‬وقــد صــادق علــى أقوالــه حتقيقـاً‪.‬‬\n      ‫وباســتجواب املدعــى عليــه الثانــي‪..... /‬ومواجهتــه بالتهمــة املنســوبة إليــه‬\n      ‫أنكر حيازته للكمية املضبوطة ‪،‬وأنها تعود ألخيه ‪ ،...../‬وعن ســبب‬\n      ‫تواجــده معــه أفــاد أنــه قــام بتوصيلــه حيــث إنــه لــم يالحظ القــات وكان‬\n      ‫بعدهــا يقصــد التوجــه إلــى األحــوال املدنيــة مبحافظــة ‪ ......‬ملراجعة قســم‬\n\n\n‫‪377‬‬\n\f‫البرنــت يريــد التقــدمي علــى وظيفــة حــارس أمــن‪ ،‬وعــن ســبب تواجــده‬\n‫بقريــة ‪.....‬أفــاد بأنــه طلــب منــه أخيــه ‪.....‬إيصالــه إلــى قريــة ‪.....‬لشــخص ال‬\n‫يعرفــه‪ ،‬وقــد صــادق علــى أقوالــه حتقيقـاً‪ .‬وقــد أســفر التحقيــق معــه عــن‬\n‫توجيــه االتهــام إلــي املدعــى عليــه األول بترويــج مــا وزنــه (‪7,13‬كجــم)‬\n‫ســبعة كيلــو وثالثــة عشــر جرام ـ ًا مــن نبــات القــات عــن طريــق النقــل‬\n‫وإلــى املدعــى عليــه الثانــي باالشــتراك يف نقــل مــا وزنــه (‪7,13‬كجــم)‬\n‫ســبعة كيلــو وثالثــة عشــر جرام ـ ًا واملجــرم مبوجــب الفقــرة الثانيــة‬\n‫مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n         ‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬مــا جــاء مبحضــر القبــض والتفتيــش املرفــق لفــه رقم(‪)1‬صفحــة‬\n                                                                        ‫رقــم(‪. )12‬‬\n              ‫‪ -2‬التقرير الكيميائي الشرعي املنوه عنه املرفق لفه (‪. )9‬‬\n‫‪ -3‬مــا جــاء باعترافــه املصــدق حتقيقــا املــدون علــى دفتــر التحقيــق‬\n                                                        ‫واملرفــق لفــة رقــم(‪)25‬‬\n‫‪ -4‬الســيارة املســتخدمة يف اجلرميــة تعــود ملكيتهــا للمتهــم الثانــي‬\n‫وكانــت بقيادتــه ســاعة القبــض وهــذه قرينــة علــى توافــر القصــد‬\n                                                                   ‫اجلنائــي لديــه‪.‬‬\n‫بالبحــث عــن ســوابقهم لــم يعثــر للمدعــى عليــه األول علــى ســوابق بينمــا‬\n‫عثــر للمدعــى عليــه الثانــي علــى ســابقة حيــازة قــات وحيــث إن مــا أقــدم‬\n‫عليــه املذكــوران فعــل محــرم شــرع ًا و معاقــب عليــه نظام ـ ًا مبوجــب‬\n‫قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات‬\n‫‪ ،‬فإنــه يتعــن إحالتهمــا إلــى احملكمــة اجلزائيــة اســتناد ًا للمــادة(‪)126‬‬\n\n\n                                                                                          ‫‪378‬‬\n\f      ‫مــن نظــام اإلجــراءات اجلزائيــة لطلــب إثبــات إدانتهمــا مبــا أســند إليهمــا‬\n      ‫واحلكــم بتعزيرهمــا يف ضــوء املــادة (الثالثــة) مــن القــرار الــوزاري‬\n      ‫املشــار إليــه أعــاه إنفــاذا لألمــر الســامي الكــرمي رقــم (‪)59633‬‬\n      ‫وتاريــخ ‪1432/12/9‬هــ‪ ،‬واحلكــم مبنعهمــا مــن الســفر بعــد انتهــاء‬\n      ‫محكوميتهــم ‪.‬واحلكــم مبصــادرة الســيارة املســتخدمة يف اجلرمية وباهلل‬\n      ‫التوفيــق وبعــرض مــا جــاء يف دعــوى املدعــي العــام علــى املدعــى عليــه‬\n      ‫األول ‪..... /‬أجــاب بصحــة واقعــة القبــض وأن الكميــة املضبوطة بحوزته‬\n      ‫والبالــغ وزنهــا (‪7,13‬كجــم) ســبعة كيلــو وثالثــة عشــر جرامـ ًا من نبات‬\n      ‫القــات احملظــور تعــود لــه لغــرض نقلهــا مــن قريــة ‪.....‬التابعــة ل ـ ‪ ........‬إلــى‬\n      ‫قريــة ‪.....‬التابعــة حملافظــة ‪ ........‬لشــخص ســعودي يدعــى‪ ...../‬وأن أخيــه‬\n      ‫املدعــو‪...../‬كان برفقتــه ويعلــم عــن الكميــة املضبوطــة‪ ،‬واســتؤجر‬\n      ‫علــى نقلهــا مببلــغ وقــدره (‪3000‬ريال)ثالثــة أالف ريــال هكــذا أجــاب‬\n      ‫وبســؤال املدعــي عليــه الثانــي ‪.....‬صــادق علــى صحــة واقعــة القبــض وأن‬\n      ‫الكميــة ألخيــه ويرغــب يف نقلهــا مــن قريــة ‪.....‬التابعــة لبنــي مالــك إلــى‬\n      ‫قريــة ‪.....‬التابعــة حملافظــة صبيــا لشــخص ســعودي يدعى‪...../‬هكــذا‬\n      ‫أجــاب وباالطــاع علــى محضــر القبــض و التحقيــق وجــد مطابــق ملــا جــاء‬\n      ‫يف الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي لفــة رقــم (‪)14‬‬\n      ‫وجــد إيجابيــة العينــة املرســلة منــه ملــادة القــات احملظــور وباالطــاع علــى‬\n      ‫صحيفــة الســوابق لــم يعثــر للمدعــى عليــه األول علــى ســوابق بينمــا عثــر‬\n      ‫للمدعــى عليــه الثانــي علــى ســابقة حيــازة قــات وبعرضهــا علــى املدعــى‬\n      ‫عليــه الثانــي صــادق عليهــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث اعتــرف املدعــى عليــه األول بترويــج الكميــة أعــاه عــن طريــق‬\n      ‫النقــل بقصــد الترويــج وحيــث اعتــرف املدعــى عليــه الثانــي باشــتراكه‬\n\n\n‫‪379‬‬\n\f‫يف نقــل القــات وحيــث إن مــا أقدمــا عليــه فعــل محــرم ومعاقــب عليــه‬\n‫نظام ـ ًا وملــا ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه األول ‪.....‬بنقــل‬\n‫مــا وزنــه (‪7,13‬كجــم) ســبعة كيلــو وثالثــة عشــر جرام ـ ًا مــن نبــات‬\n‫القــات احملظــور عــن طريــق النقــل بقصــد الترويــج كمــا ثبــت لــدي إدانــة‬\n‫املدعــى عليــه الثانــي ‪.....‬باشــتراكه يف نقــل القــات ونظــر ًا لصغــر حجــم‬\n‫الكميــة ولقناعــة احملكمــة بظروفهمــا االجتماعيــة فقــد قــررت النزول‬\n‫عــن احلــد األدنــى للعقوبــة املقــررة يف املــادة الثالثــة وحكمــت عليهمــا‬\n‫تعزيــر ًا بالســجن ملــدة ســتة أشــهر اعتبــارا مــن تاريــخ توقيفهمــا وغرامــة‬\n‫ماليــة علــى كل واحــد منهمــا قدرهــا ألــف ريــال اســتنادا للمــادة الثالثــة‬\n‫مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ املعــدل بقــراري وزيــر‬\n‫الداخليــة رقــم (‪)2057‬لعــام ‪1404‬ه ـ ورقم(‪)3818‬لعــام ‪1410‬ه ـ إنفــاذ ًا‬\n‫لألمــر الســامي الكــرمي رقــم (‪ )59633‬يف ‪1433/12/9‬ه ـ القاضــي‬\n‫باســتثناء عقوبــات قضايــا القــات مــن نظــام مكافحــة املخــدرات‬\n‫الصــادر باملرســوم امللكــي رقــم ‪ 39 /‬وتاريــخ ‪1426/7/8‬ه ـ كمــا‬\n‫حكــت مبنعهمــا مــن الســفر خــارج اململكــة ملــدة ســنتني بعــد انتهــاء‬\n‫محكوميتهمــا اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم‪ 69935‬يف‬\n‫‪1433/6/18‬ه ـ كمــا صرفــت النظــر عــن طلــب املدعــي العــام مصــادرة‬\n‫الســيارة املوضحــة بعاليــة واالكتفــاء بالعقوبــة احملكــوم بهــا وبهــذا‬\n‫انتهــت هــذه الدعــوى وبعــرض مــا حكمنــا بــه علــى املدعــى عليــه قنــع بــه‬\n‫وقــرر املدعــي العــام املعارضــة وطلــب رفعهــا حملكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/25‬ه ـ‬\n‫تابــع دعــوى املدعــي العــام ضــد ‪..... /‬و ‪ .....‬يف قــات‪ .‬احلمــد هلل وحــده‬\n\n\n                                                                                     ‫‪380‬‬\n\f      ‫والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي هــذا اليــوم االثنــن‬\n      ‫املوافــق ‪1434/04/01‬ه ـ افتتحــت اجللســة بنــاء علــى ورود املعاملــة‬\n      ‫املتعلقــة بهــذه الدعــوى مــن محكمــة االســتئناف مبنطقــة عســير برقــم‬\n      ‫(‪)34584255‬يف ‪1434/03/07‬ه ـ ومرفــق بهــا قــرار أصحــاب الفضيلــة‬\n      ‫قضــاة الدائــرة اجلزائيــة الثالثــة رقــم(‪)3441120‬يف ‪1434/02/19‬ه ـ‬\n      ‫املتضمــن مالحظــة مــا يلــي ‪ :‬أن فضيلتــه لــم يرفــق صــورة تعميــم ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪ )69935‬يف ‪1433/6/18‬ه ـ الــذي اســتند عليــه‬\n      ‫يف حكمــه مبنــع املدعــى عليهمــا مــن الســفر خــارج اململكــة‪ .‬فعلــى‬\n      ‫فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق ‪ .‬رئيــس‬\n      ‫الدائــرة الشــيخ‪ .....‬ختمــه و توقيعــه قاضــي اســتئناف الشــيخ ‪.....‬ختمــه و‬\n      ‫توقيعــه قاضــي اســتئناف الشــيخ ‪.....‬ختمــه و توقيعــه أ‪.‬هـ‪ .‬أجيب أصحاب‬\n      ‫الفضيلــة أنــه مت إرفــاق صــورة التعميــم واهلل املوفــق وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وآلــه وصحبــه أجمعــن ‪ .‬حــرر يف ‪1434/04/01‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمة اجلزائيــة بجازان برقم ‪34584255‬‬\n      ‫وتاريخ‪1434/4/2‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ .... /‬برقــم ‪ 3422247‬وتاريــخ ‪1434/1/25‬هـ اخلاص‬\n      ‫بدعــوى املدعــي العــام ضــد كل مــن ‪..... /‬و‪ .....‬يف قضيــة ( ترويــج قــات‬\n      ‫) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة‬\n      ‫ـاء علــى قرارنــا رقــم ( ‪ ) 3441120‬وتاريــخ ‪1434/2/19‬ه ـ ‪.‬‬         ‫ضبطــه بنـ ً‬\n\n‫‪381‬‬\n\f‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى‬\n                              ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪382‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":375,"source_page_end":382,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5e72b2a3e7b0fe6ddfa53525c3f8d776783e6862260551774ec7c7f6019fb48e","normalized_text_hash":"c4a04668b4883b00328f39af4676216eb7faf08bcfe3655bc60b5775f1e05629","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p375-3422247"},{"id":"81bf98fd-fbda-5ad6-b275-3c15a4391cc0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة «االمفيتامن» -التوسط يف بيع احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق -تعزير بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال والشريحة املستخدمة يف اجلرمية.","document_number":"3432281","case_number":"3435959","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/6","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة «االمفيتامن» -التوسط يف بيع احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق -تعزير بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال والشريحة املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3432281 :‬تاريخه‪1434/2/6 :‬هـ‬\n                          ‫رقم الدعوى‪3435959:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3442187‬تاريخه‪1434/2/19 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة «االمفيتامــن» ‪ -‬التوســط يف‬\n      ‫بيــع احلبــوب احملظــورة ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة املدعــى‬\n      ‫عليــه ‪ -‬عــدم وجــود ســوابق ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع‬\n      ‫مــن الســفر ومبصــادرة اجلــوال والشــريحة املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n      ‫مــن املــادة (‪ )56‬واملــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات ( حبــوب‬\n      ‫اإلمفيتامــن احملظــورة ) مت القبــض علــى املدعــى عليــه وهــو يســلم‬\n      ‫املصــدر الســري حبــوب اإلمفيتامــن ‪ ،‬أقــر املدعــى عليــه بالترويــج‪،‬‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n      ‫اإلمفيتامــن‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبــة‬\n      ‫تعزيريــة بحقــه لقــاء توســطه يف بيــع احلبــوب احملظــورة وتعاطيــه‪ ،‬واملنــع‬\n      ‫مــن الســفر خــارج البــاد بعــد تنفيــذ العقوبــة ومصــادرة اجلــوال املســتخدم‬\n      ‫يف الترويــج وإلغــاء الشــريحة املســتخدمة يف الترويــج وعــدم صرفهــا‬\n\n‫‪383‬‬\n\f‫لنفــس املتهــم مــرة أخــرى‪ ،‬حكمــت احملكمــة بثبــوت إدانــة املدعــى‬\n‫عليــه بالتوســط ببيــع احلبــوب احملظــورة‪ ،‬فقــررت احملكمــة احلكــم‬\n‫علــى املدعــى عليــه بســجنه ســنتني تبــدأ مــن تاريــخ توقيفــه يف هــده‬\n‫القضيــة‪ ،‬وإلزامــه بدفــع غرامــة ماليــة قدرهــا ثالثــة آالف ري ــال‪ ،‬وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة‬\n‫بــن كل دفعــة وأخــرى عشــرة أيــام‪ ،‬ومنعــه مــن الســفر خلــارج البــاد‬\n‫ملــدة ســنتني بعــد انتهــاء مــدة محكوميتــه‪ ،‬ومصــادرة اجلــوال املســتخدم‬\n‫يف الترويــج وإلغــاء الشــريحة املســتخدمة يف الترويــج وعــدم صرفهــا‬\n‫لنفــس املتهــم مــرة أخــرى‪ ،‬وقــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬وجــرى‬\n                        ‫تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائية بخميس مشــيط برقــم ‪..........‬وتاريخ ‪1434/01/20‬ه‬\n‫املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪1434/01/20‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق ‪ 1434/02/05‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام وادعــى علــى ‪..........‬ســعودي مبوجــب ســجل مدنــي رقــم‬\n‫(‪ )..........‬جهــة االصــدار خميــس مشــيط املهنــة طالــب متهــم بالوســاطة‬\n‫ا يف دعــواه أنــه يف مســاء‬\n                           ‫يف املــواد املخــدرة وال يوجــد عليــه ســوابق قائـ ً‬\n‫يــوم األربعــاء املوافــق ‪1433/12/8‬ه ـ وإثــر توفــر معلومــات عــن قيــام‬\n‫املدعــى عليــه بترويــج احلبــوب احملظــورة مت تكليــف أحــد مصــادر‬\n‫مكافحــة املخــدرات الســرية بخميــس مشــيط باالتصــال علــى جوالــه‬\n\n                                                                                    ‫‪384‬‬\n\f      ‫رقــم (‪ )..........‬واالتفــاق معــه علــى شــراء حبتــن مــن احلبــوب احملظــورة‬\n      ‫مبلــغ مائــة ريــال (‪ )100‬وقــد حــدد للمصــدر موقــع اللقــاء أمــام ســوق‬\n      ‫‪..........‬علــى طريــق ‪ .............‬ومــن ثــم ذهــب املصــدر وبرفقتــه أحــد‬\n      ‫األفــراد إلــى املوقــع وركــب معهــم املدعــى عليــه واجتهــوا إلــى إشــارة‬\n      ‫األزمــة وتقابلــوا مــع أحــد األشــخاص (مت فــرز أوراق مســتقلة لــه) وقــام‬\n      ‫املدعــى عليــه بتســليم احلبــوب للمصــدر حتــت أنظــار الفــرد املتنكــر‬\n      ‫ومت القبــض عليــه عنــد إنزالــه يف أســواق‪..........‬وضبط معــه اجلــوال‬\n      ‫املســتخدم يف الترويــج ذى الرقــم املصنعــي (‪ )..........‬وبســماع أقوالــه‬\n      ‫أقــر بالتوســط يف بيــع حبتــن مــن احلبــوب احملظــورة وتعاطيــه مــن نوعهــا‬\n      ‫املضبــوط ولنوعهــا يف الســابق وباســتجواب املدعــى عليــه املذكــور أقــر‬\n      ‫بالتوســط يف بيــع حبتــن مــن احلبــوب احملظــورة عــن طريــق االســتالم‬\n      ‫والتســليم وأن اجلــوال ذو الرقــم (‪ )..........‬يعــود لــه وبتحليــل عينــة ممــا‬\n      ‫مت ترويجــه ثبــت احتوائهــا علــى مــادة االمفيتامــن احملظــورة مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪1433‬ه ـ الصــادر مــن‬\n      ‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة عســير‬\n      ‫واالمفيتامــن مــن املــواد املدرجــة باجلــدول الثانــي فئــة (ب) املــواد املخــدرة‬\n      ‫امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد انتهــى‬\n      ‫التحقيــق معــه إلــى توجيــه االتهــام إليــه بترويــج حبتــن (‪ )2‬مــن احلبــوب‬\n      ‫احملظــورة عــن طريــق االســتالم والتســليم وتعاطيــه مــن نــوع املضبــوط‬\n      ‫ولنوعــه يف الســابق واملجــرم مبوجــب املــادة (‪ )3‬الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ /1‬محضــر الشــراء والقبــض والتفتيــش ‪ /2‬إقــرار املتهــم املــدون مبلــف‬\n\n\n‫‪385‬‬\n\f‫التحقيــق ‪ /3‬محضــر ســماع األقــوال ‪ /4‬التقريــر الكيميائــي الشــرعي‬\n‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم وجــرم ومعاقــب عليــه‬\n‫شــرع ًا ونظامـ ًا واملجــرم مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة لــذا أطلــب إثبــات إدانتــه مبــا نســب إليــه واحلكــم عليــه مبــا‬\n‫يلــي‪ /1 :‬عقوبــة تعزيريــة بحقــه وفقـ ًا ملــا ورد يف املــادة (‪ )1/38‬مــن نظــام‬\n‫املخــدرات واملؤثــرات العقليــة لقــاء مــا نســب إليــه واحلكــم عليــه بالعقوبة‬\n‫األشــد إعمــا ًال للمــادة (‪ )62‬مــن النظــام املشــار إليــه لقــاء توســطه يف بيــع‬\n    ‫احلبــوب احملظــورة وتعاطيــه مــن نــوع املضبــوط ولنوعهــا يف الســابق‬\n‫‪ /2‬منعــه مــن الســفر خــارج اململكــة العربيــة الســعودية بعــد تنفيــذ‬\n‫العقوبــة وفقـ ًا ملــا ورد يف املــادة (‪ )1/56‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه الفقــرة األولــى ‪ /3‬مصــادرة اجلــوال ذي الرقــم املصنعــي‬\n‫(‪ )..........‬املســتخدم يف الترويــج إســتناد ًا للمــادة (‪ )53‬مــن النظــام املشــار‬\n‫إليــه وإلغــاء الشــريحة رقــم (‪ )..........‬وعــدم صرفهــا لنفــس املســتخدم‬\n‫إســتناد ًا لتعميم ســمو وزير الداخلية رقم (‪ )9798‬يف ‪1428/2/10-9‬هـ‬\n‫هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب‬\n‫قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن توســطي يف بيــع حبتــن مــن احلبــوب‬\n‫احملظــورة عــن طريــق االســتالم والتســليم كلــه صحيــح وأنــا تائــب‬\n‫ونــادم هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى محضــر القبــض‬\n‫والتفتيــش بتاريــخ ‪1433/12/8‬ه ـ واملتضمــن أنــه ورد بــاغ مــن أفــراد‬\n‫البحــث يفيــد بــأن هنــاك شــخص يقــوم بترويــج احلبــوب وبعــد ذلــك قــام‬\n‫املصــدر باالتصــال باملدعــى عليــه حيــث توســط علــى شــراء حبتــن‬\n‫مببلــغ مائــة ريــال وقــد حــدد الوســيط املوقــع الــذي ســيقابل املصــدر فيــه‬\n‫وركــب مــع املصــدر الســري واجتهــوا ملقابلــة املــروج ومتــت املبايعــة هــذا‬\n\n\n                                                                                         ‫‪386‬‬\n\f      ‫وقــد جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي رقــم (‪)..........‬‬\n      ‫لعــام ‪1433‬ه ـ املتضمــن إيجابيــة العينــة املضبوطــة ملــادة اإلمفيتامــن‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث صــادق املدعــى عليــه‬    ‫فبنـ ً‬\n      ‫ـاء علــى محضــر القبــض والتفتيــش‬       ‫علــى صحــة دعــوى املدعــي العــام وبنـ ً‬\n      ‫والتقريــر الكيميائــي املشــار إليهمــا أعــاه ونظــر ًا ألن املدعــى عليــه‬\n      ‫يســتحق عقوبــة طبق ـ ًا للقواعــد الشــرعية ووفق ـ ًا للمادتــن (‪، )38‬‬\n      ‫(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ونظــر ًا لقلــة‬\n      ‫الكميــة التــي توســط بهــا وخللــو صحيفــة املدعــى عليــه مــن الســوابق وملــا‬\n      ‫قــرره مــن التوبــة والنــدم ونظــر ًا لصغــر ســنه وملقتضــى املــادة (‪ )60‬مــن‬\n      ‫ـدي إدانــة املدعــى عليــه‬\n                                ‫النظــام املشــار إليــه ولــكل مــا تقــدم فقــد ثبــت لـ ّ‬\n      ‫بالتوســط ببيــع حبتــن مــن احلبــوب احملظــورة وحكمــت بتعزيــره لقــاء‬\n      ‫ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجن املدعــى عليــه ملــدة ســنتني مــن تاريــخ إيقافــه‬\n      ‫ـاء علــى املادتــن (‪ )60،38‬مــن نظــام مكافحــة‬          ‫بســبب هــذه القضيــة بنـ ً‬\n      ‫املخــدرات واملؤثــرات العقليــة وإلزامــه بدفــع غرامــة ماليــة قدرهــا ثالثــة‬\n      ‫آالف ريــال وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــه‬\n      ‫خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام‪ .‬ثاني ـاً‪ :‬منعــه مــن‬\n      ‫ـاء علــى‬\n              ‫الســفر خــارج البــاد ملــدة ســنتني بعــد انتهــاء مــدة محكوميتــه بنـ ً‬\n      ‫املــادة (‪ )56‬مــن النظــام املشــار إليــه أعــاه ‪ .‬ثالث ـاً‪ :‬مصــادرة اجلــوال ذى‬\n      ‫ـاء علــى املــادة (‪)53‬‬‫الرقــم املصنعــي (‪ )..........‬املســتخدم يف الترويــج بنـ ً‬\n      ‫مــن النظــام املشــار إليــه وإلغــاء الشــريحة رقــم (‪ )..........‬وعــدم صرفــه‬\n      ‫النفــس املســتخدم اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم (‪)9798‬‬\n      ‫بتاريــخ ‪1428/2/10-9‬ه ـ ومبــا تقــدم حكمــت وبإعــان احلكــم قــرر‬\n      ‫املدعــي العــام االعتــراض بــدون الئحــة اعتراضيــة وقــرر املدعــى عليــه‬\n\n\n‫‪387‬‬\n\f‫القناعــة وأمــرت برفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم وجــرى النطــق باحلكــم بتاريــخ ‪1434/2/5‬ه ـ الســاعة‬\n‫الثانيــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n‫‪..........‬وتاريــخ ‪1434 /4/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة‬\n‫القاضــي باحملكمــة الشــيخ ‪.......... /‬برقــم ‪..........‬وتاريــخ ‪1434/2/6‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد‪.......... /‬قضيــة ( مخــدرات ) علــى‬\n‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه عليــه تقــررت املوافقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪388‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":383,"source_page_end":388,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d9d5f8e2ea85972a83d48f69ae2eea49bb539adf0115d12d9360faa78af9170b","normalized_text_hash":"010cb5e826f850eef2bc6b5a9a72020c1854b8bd06299bca22504555aceb20dc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p383-3432281"},{"id":"9271348b-3a01-55a0-a7a9-164991ac911c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة «االمفيتامن» -تعاطي احلبوب احملظورة -توسط يف بيع احلبوب احملظورة -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -عدم مصادرة السيارة ألنها باسم شخص آخر -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال والشريحة املستخدم يف اجلرمية .","document_number":"3432301","case_number":"3438013","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/6","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة «االمفيتامن» -تعاطي احلبوب احملظورة -توسط يف بيع احلبوب احملظورة -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -عدم مصادرة السيارة ألنها باسم شخص آخر -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال والشريحة املستخدم يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3432301 :‬تاريخه‪1434/2/6 :‬هـ‬\n                          ‫رقم الدعوى‪3438013:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3451862‬تاريخه‪1434/3/1 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة «االمفيتامــن» ‪ -‬تعاطي احلبوب‬\n      ‫احملظــورة ‪ -‬توســط يف بيــع احلبــوب احملظــورة ‪ -‬ثبــوت إدانــة املدعــى‬\n      ‫عليــه ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬عــدم مصــادرة الســيارة ألنهــا‬\n      ‫باســم شــخص آخــر ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن‬\n             ‫الســفر ومصــادرة اجلــوال والشــريحة املســتخدم يف اجلرميــة ‪.‬‬\n\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬واملــادة (‪ )60‬مــن‬\n                                       ‫نظــام مكافحــة املخــدرات واملؤثــرات العقلية‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليهمــا لقيامهمــا بترويــج حبــوب اإلمفيتامني‬\n      ‫احملظــورة ‪ ،‬مت القبــض علــى املدعــى عليهمــا وبحوزتهمــا حبــوب‬\n      ‫اإلمفيتامــن ‪ ،‬إقرارهمــا بصفــة الترويــج والتعاطــي والتوســط يف بيــع‬\n      ‫احلبــوب احملظــورة ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة‬\n      ‫املضبوطــة علــى اإلمفيتامــن‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n      ‫ـاء علــى مــا ورد يف نصــوص نظــام مكافحــة املخــدرات‬         ‫عليهمــا‪ ،‬بنـ ً‬\n      ‫واملؤثــرات العقليــة‪ ،‬بعقوبــة تعزيريــة ومنعهمــا مــن الســفر خــارج البــاد‬\n      ‫بعــد تنفيــذ العقوبــة عليهمــا مصــادرة جهــازي اجلــوال املســتخدم يف‬\n\n‫‪389‬‬\n\f‫الترويــج وإلغــاء الشــريحة املســتخدمة يف الترويــج وذلــك الســتخدامهما‬\n‫يف قضيــة الترويــج‪ ،‬ومصــادرة الســيارة املســتخدمة يف عمليــة الترويــج‪،‬‬\n‫إلــزام املدعــى عليــه الثانــي بدفــع املبلــغ احلكومــي‪ ،‬حكمــت احملكمــة‬\n‫بثبــوت إدانــة املدعــى عليهمــا بترويــج احلبــوب احملظــورة‪ ،‬فقــررت‬\n‫احملكمــة احلكــم علــى املدعــى عليــه األول بالســجن ثــاث ســنوات‬\n‫مــن تاريــخ التوقيــف‪ ،‬وجلــده مائــة وخمســن جلــدة علــى ثالثــة فتــرات‬\n‫متســاويات بــن كل فتــرة وأخــرى عشــرة أيــام منهــا فتــرة واحــدة علنــا‬\n‫يف مــكان عــام‪ ،‬وبعــد تنفيــذ اجللــد الســابق يجلــد ســبعني جلــدة دفعــة‬\n‫واحــدة لقــاء تعاطيــه احلبــوب احملظــورة‪ ،‬ويدفــع غرامــة ماليــة تــودع يف‬\n‫خزينــة الدولــة العامــة‪ ،‬مصــادرة جوالــه الســتخدامه يف التنســيق لعمليــة‬\n‫الترويــج‪ ،‬ومينــع مــن الســفر خــارج البــاد ملــدة ثــاث ســنوات‪ ،‬وعلــى‬\n‫املدعــى عليــه الثانــي ســجنه ســبعة وعشــرون شــهرا مــن تاريــخ التوقيــف‪،‬‬\n‫جلــده مائــة جلــدة علــى فترتــن متســاويتني بينهمــا عشــرة أيــام إحداهمــا‬\n‫علنــا يف مــكان عــام‪ ،‬ويدفــع غرامــة ماليــة تــودع يف خزينــة الدولــة‬\n‫العامــة‪ ،‬ومينــع الســفر خــارج البــاد ملــدة ســنتني وثالثــة أشــهر‪ ،‬وقــرر‬\n‫املدعــى عليهمــا عــدم قناعتهمــا باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن‬\n                                                  ‫قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية بخميس مشيط برقم ‪..........‬وتاريخ ‪1434/01/21‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪1434/01/21‬ه ـ ففــي يــوم‬\n\n                                                                                     ‫‪390‬‬\n\f      ‫الثالثــاء املوافــق ‪1434/02/05‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n      ‫‪01‬وفيهــا حضــر املدعــي العــام ‪ ،..........‬املكلــف بخطــاب التكليــف‬\n      ‫رقــم ‪ 51‬وتاريــخ ‪1430/5/8‬ه ـ ‪ ،‬وادعــى علــى احلاضريــن يف مجلــس‬\n      ‫القضــاء كال مــن ‪ ،..........‬قائــا يف دعــواه انتهــى التحقيــق مــع‬\n      ‫املذكوريــن إلــى توجيــه االتهــام إلــى املدعــى عليــه األول ‪ ..........‬بترويــج‬\n      ‫أربــع حبــات مــن احلبــوب املنبهــة احملظــورة عــن طريــق البيــع علــى أحــد‬\n      ‫مصــادر املخــدرات الســرية بعــد أن أحضرهــا علــى ســيارة مــن نــوع ‪......‬‬\n      ‫صنــع ‪2007‬م رقــم لوحتــه ‪، ....‬وللثانــي ‪..........‬بترويــج عشــرين حبــه مــن‬\n      ‫احلبــوب املنبهــة احملظــورة عــن طريــق البيــع علــى أحــد املصــادر الســرية‬\n      ‫ملكافحــة املخــدرات مقابــل مبلــغ قــدره تســعمائة ريــال بعــد التنســيق‬\n      ‫معــه علــى جوالــه ذي الرقــم ‪ ،..........‬واســتعماله للحبــوب احملظــورة مــن‬\n      ‫املضبــوط واســتعمالها يف الســابق ‪ ،‬وبتحليــل عينــة ممــا مت ضبطــه ثبــت‬\n      ‫احتواءهــا علــى مــادة االمفيتامــن املنبهــة احملظــورة مبوجــب التقريــر‬\n      ‫الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n      ‫الطبيــة الشــرعية مبنطقــة عســير برقــم ‪..........‬لعــام ‪1433‬ه واملرفــق علــى‬\n      ‫اللفــة ‪ ،18‬وبالبحــث عــن ســوابقهما اتضــح عــدم وجــود ســوابق مســجلة‬\n      ‫عليهمــا ‪،‬لــذا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة‬\n      ‫تعزيريــة وفقــا ملــا ورد يف املــادة ‪ 1/38‬مــن نظــام املخــدرات واملؤثــرات‬\n      ‫العقليــة لقــاء مــا نســب إليهمــا مــن الترويــج‪ ،‬وإجــراء املقتضــى الشــرعي‬\n      ‫بحــق املدعــى عليــه الثانــي لقــاء تعاطيــه للحبــوب احملظــورة ‪،‬ومنعهمــا‬\n      ‫مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة عليهمــا وفقــا ملــا ورد‬\n      ‫يف املــادة ‪ 1/56‬مــن ذات النظــام ‪ ،‬ومصــادرة الســيارة املســتخدمة يف‬\n      ‫عمليــة الترويــج وهــي مــن نــوع ‪ .....‬صنــع ‪2007‬م ‪ ،‬ومصــادرة اجلــوال‬\n\n\n‫‪391‬‬\n\f‫ذي الرقــم املصنعــي رقــم ‪..........‬وفقــا ملــا ورد يف املــادة ‪ ، 1/53‬وإلغــاء‬\n‫الشــريحة الهاتفيــة رقــم ‪ ،..........‬وإلــزام املدعــى عليــه الثانــي بدفــع املبلــغ‬\n‫احلكومــي املرقــم وقــدره تســعمائة ريــال ‪ ،‬هكــذا ادعــى‪ ،‬وبســؤال‬\n‫املدعــى عليهمــا قــاال إن جميــع مــا ذكــره املدعــي العــام يف دعــواه‬\n‫صحيــح جملــة وتفصيــا حيــث أننــي قمــت أنــا ‪..........‬بترويــج عــدد أربــع‬\n‫حبــات محظــورة عــن طريــق البيــع علــى أحــد املصــادر الســرية ملكافحــة‬\n‫املخــدرات بعــد أن أحضرتهــا علــى الســيارة املذكــورة يف الدعــوى ‪،‬‬\n‫وتلــك الســيارة تعــود ملكيتهــا البــن عمــي الــذي لــم يكــن يعلــم بأننــي‬\n‫اســتخدمت ســيارته يف عمليــة الترويــج هــذه ‪ ،‬وقمــت أنــا بترويــج عــدد‬\n‫عشــرين حبــة محظــورة عــن طريــق البيــع علــى أحــد املصــادر الســرية‬\n‫ملكافحــة املخــدرات ‪،‬مببلــغ تســعمائة ريــاال بعــد التنســيق معــي علــى‬\n‫جوالــي املذكــور يف الدعــوى ‪ ،‬وتوســطت يف ترويــج ثــاث حبــات‬\n‫محظــورة عــن طريــق البيــع ‪،‬واســتلمت املبلــغ احلكومــي املرقــم ولــم‬\n‫أعــده ‪ ،‬وتعاطيــت احلبــوب احملظــورة ‪،‬هكــذا أجابــا‪ ،‬وبســؤال املدعــي‬\n‫العــام عــن مالــك الســيارة فقــال صحيــح أنهــا للمدعــو ‪..........‬حســب اللفــة‬\n‫‪ 10‬مــن أوراق املعاملــة إال أنهــا أســتخدم يف عمليــة الترويــج لــذا متــت‬\n‫املطالبــة مبصادرتهــا ‪ ،‬فنظــرا إلــى مــا ورد يف الدعــوى ‪ ،‬وإلــى إقــرار‬\n‫املدعــى عليهمــا مبــا نســب إليهمــا ‪ ،‬ومــا نســب إليهمــا مــن الترويــج‬\n‫موجــب لعقابهمــا مبــا دون احلــد األدنــى مــن عقوبــة الســجن الــواردة يف‬\n‫مــادة النظــام املشــار إليهــا يف الدعــوى ‪،‬نظــرا إلــى املــادة الســتني مــن ذات‬\n‫النظام ‪ ،‬لعدم وجود سوابق مسجلة على املدعى عليهما ‪ ،‬إال أنه يؤخذ‬\n‫يف االعتبــار عنــد تقريــر العقــاب أن املدعــى عليــه الثانــي ‪..........‬يأتــي يف‬\n‫الدرجــة األول مــن العقــاب لكثــرة عــدد احلبــوب املروجــة ‪ ،‬ويأتــي يف‬\n\n\n                                                                                           ‫‪392‬‬\n\f      ‫الدرجــة الثانيــة املدعــى عليــه الثانــي ‪..........‬لقلــة احلبــوب التــي روجهــا ‪،‬‬\n      ‫ويعــزر املدعــى عليــه الثانــي مبــا دون حــد املســكر لقــاء تعاطيــه احلبــوب‬\n      ‫احملظــورة ألنهــا منبهــة وليســت مخــدرة‪ ،‬وأمــا الســيارة فلــم يظهــر لــي‬\n      ‫القــول مبصادرتهــا مــا دام أنهــا باســم شــخص آخــر غيــر املدعــى عليهمــا‬\n      ‫ولــم يظهــر لــه أي اشــتراك يف هــذه القضيــة كمــا أن احلبــوب املروجــة‬\n      ‫عليهــا قليلــة ‪ ،‬ومــادام أســتخدم املدعــى عليــه الثانــي جوالــه يف التنســيق‬\n      ‫لعمليــة الترويــج هــذه فالبــد مــن مصادرتــه كمــا البــد مــن إلزامــه بإعادة‬\n      ‫املبلــغ احلكومــي املرقــم الــذي اســتلمه ولــم يعــده‪ .‬وبنــاء علــى كل مــا‬\n      ‫تقــدم فقــد ثبــت لــدي ترويــج املدعــى عليــه ‪..........‬لعــدد عشــرين حبــة‬\n      ‫محظــورة عــن طريــق البيــع وتوســطه يف ترويــج ثــاث حبــات محظــورة‬\n      ‫‪ ،‬ويســجن لقــاء ذلــك ثــاث ســنوات مــن تاريــخ التوقيــف ‪ ،‬ويجلــد مائــة‬\n      ‫وخمســن جلــدة علــى ثــاث فتــرات متســاويات بــن كل فتــرة وأخــرى‬\n      ‫عشــرة أيــام منهــا فتــرة واحــدة علنــا يف مــكان عــام ‪ ،‬ويدفــع غرامــة‬\n      ‫ماليــة قدرهــا ألــف وخمســمائة ريــال تــودع يف خزينــة الدولــة العامــة ‪،‬‬\n      ‫وبعــد اجللــد الســابق بخمســة عشــر يومــا يجلــد املذكــور ســبعني جلــدة‬\n      ‫دفعــة واحــدة لقــاء تعاطــي احلبــوب احملظــورة ‪ ،‬ويتــم مصــادرة جوالــه‬\n      ‫املذكــور رقمــه املصنعــي يف الدعــوى مــع عــدم صــرف الشــريحة لنفــس‬\n      ‫املشــترك بعــد إلغائهــا وتــودع القيمــة يف خزينــة الدولــة العامــة ‪ ،‬ويلــزم‬\n      ‫بدفــع مبلــغ تســعمائة ريــال إلدارة مكافحــة مخــدرات خميــس مشــيط‬\n      ‫‪ ،‬وبعــد تنفيــذ احلكــم عليــه مينــع مــن الســفر إلــى خــارج اململكــة ملــدة‬\n      ‫ثــاث ســنوات ‪ ،‬كمــا ثبــت ترويــج املدعــى عليــه ألربــع حبــات محظــورة‬\n      ‫عــن طريــق البيــع ويســجن لقــاء ذلــك ســبعة وعشــرين شــهرا مــن تاريــخ‬\n      ‫التوقيــف ويجلــد مائــة جلــدة علــى فترتــن متســاويتني بينهمــا عشــرة أيــام‬\n\n\n‫‪393‬‬\n\f‫إحداهمــا علنــا يف مــكان عــام ‪ ،‬ويدفــع غرامــة ماليــة قدرهــا ألــف ريــال‬\n‫تــودع يف خزينــة الدولــة العامــة ‪ ،‬وبعــد تنفيــذ احلكــم عليــه مينــع مــن‬\n‫الســفر إلــى خــارج اململكــة ملــدة ســنتني وثالثــة أشــهر ‪ ،‬وصرفــت النظــر‬\n‫عــن مطالبــة املدعــي العــام مبصــادرة الســيارة املذكــورة يف الدعــوى ملــا‬\n‫ذكرتــه يف احليثيــات أعــاه ‪ ،‬ومبــا تقــدم حكمــت ‪ ،‬وبعــرض احلكــم‬\n‫عليهمــا قــاال إننــا مقتنعــان بــه ‪ ،‬وقــال املدعــي العــام إننــي معتــرض علــى‬\n‫احلكــم واطلــب رفعــة إلــى محكمــة االســتئناف دون الئحــة اعتراضية ‪،‬‬\n‫وبــذا انتهــت يف الســاعة الثانيــة والنصــف ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/05‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس‬\n‫مشــيط برقــم ‪ 34/186142‬وتاريــخ بــدون املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.......... /‬برقــم ‪..........‬وتاريــخ‬\n‫‪1434/02/06‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد كل مــن ‪/‬‬\n‫‪ ....................‬يف قضيــة ( مخــدرات ) علــى الصفــة املوضحــة يف القــرار‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n\n\n\n\n                                                                                       ‫‪394‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":389,"source_page_end":394,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"68113c604659c2a75d6f0d9df218bf52ec27caefece1b971163ca8fdf179b0b1","normalized_text_hash":"ba31e72fdf4c688239cc95a0193eea6d9ff079b64683d2bd7b982349ee429e48","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p389-3432301"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

